def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent.

    Given a list of classes, this function removes any class that is
    a subclass of another class in the list, preserving the original
    order of the remaining classes.
    """
    classes = tuple(classes)
    result = []
    for i, c in enumerate(classes):
        if not isinstance(c, type):
            raise TypeError(f"Expected class objects in sequence, got {c!r}")
        redundant = False
        for j, d in enumerate(classes):
            if i == j:
                continue
            try:
                if issubclass(c, d):
                    redundant = True
                    break
            except TypeError:
                # d is not a class; ignore
                continue
        if not redundant:
            result.append(c)
    return result<|return|>

