def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    import inspect

    # Gather the relevant classes from the method resolution order
    classes = [self.__class__] if not all else list(inspect.getmro(self.__class__))
    descs = []
    seen = set()

    for cls in classes:
        for name, member in cls.__dict__.items():
            # Skip private or magic attributes
            if name.startswith("_"):
                continue
            # Avoid duplicates when inheriting
            if name in seen:
                continue
            seen.add(name)
            # Get the docstring of functions, properties, methods etc.
            doc = None
            try:
                # For descriptors like property, get __doc__
                doc = member.__doc__
            except AttributeError:
                pass
            if doc is None:
                # Try to get doc from functions if available
                if callable(member):
                    doc = inspect.getdoc(member)
            # If still None, try attribute of the instance
            if doc is None and hasattr(self, name):
                try:
                    attr = getattr(self, name)
                    doc = getattr(attr, "__doc__", None)
                except Exception:
                    doc = None
            if doc is None:
                doc = ""
            descs.append((name, doc))
    # Sort results by attribute name
    descs.sort(key=lambda x: x[0])
    return descs<|return|>

