def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    import numpy as np
    # Ensure inputs are NumPy arrays
    bins = np.asarray(bins)
    edges = np.asarray(edges)
    # Handle 1‑D edges list
    if edges.ndim == 1:
        if bins.shape[0] != edges.shape[0] - 1:
            raise ValueError("Number of bins must equal number of edges minus one.")
        widths = np.diff(edges)
        return np.sum(bins * widths)
    # Handle multi‑dimensional edges
    if isinstance(edges, (list, tuple)):
        diff_edges = [np.diff(e) for e in edges]
    else:
        # In case edges is an ndarray of shape (ndim, )
        diff_edges = [np.diff(e) for e in edges]
    # Build an array of bin widths that broadcasts to the bins shape
    try:
        widths = np.multiply.reduce(np.ix_(*diff_edges))
    except Exception:
        # If edges is 1D disguised as list, fall back
        widths = np.diff(edges)
    if widths.shape != bins.shape:
        if widths.shape == (diff_edges[0].shape[0],):
            # Should match shape for 1D case
            widths = np.diff(edges)
        else:
            raise ValueError("Shape of bin widths does not match shape of bins.")
    return np.sum(bins * widths)<|return|>

