def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        # If either is not a dict, nothing to compare at this level
        return {}

    result = {}
    for key, val1 in d1.items():
        if key not in d2:
            # key missing in d2: copy reference (may be a subdict)
            result[key] = val1
            continue

        val2 = d2[key]

        if isinstance(val1, dict) and isinstance(val2, dict) and level != 0:
            # Recurse into subdicts, respecting depth parameter
            next_level = level - 1 if level > 0 else level
            subdiff = difference(val1, val2, next_level)
            if subdiff:
                result[key] = subdiff
            continue

        # Otherwise, if values differ, include the value from d1
        if val1 != val2:
            result[key] = val1

    return result<|return|>

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.
    """
    def _diff(a, b, depth):
        result = {}
        # True for unlimited recursion
        unlimited = depth < 0
        for key, val_a in a.items():
            if key not in b:
                # key missing in second dict: include whole value
                if isinstance(val_a, dict):
                    # return nested dict directly (no copy to avoid side effects)
                    result[key] = val_a
                else:
                    result[key] = val_a
            else:
                val_b = b[key]
                if isinstance(val_a, dict) and isinstance(val_b, dict):
                    # both values are dicts – recurse if depth allows
                    if unlimited or depth > 0:
                        sub = _diff(val_a, val_b, depth - 1 if depth > 0 else depth)
                        if sub:
                            result[key] = sub
                else:
                    # non-dict values: include if different
                    if val_a != val_b:
                        result[key] = val_a
        return result

    # Build the result by calling the helper
    return _diff(d1, d2, level) if isinstance(d1, dict) and isinstance(d2, dict) else {}
<|return|>

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """
    # If d1 is not a dict, nothing to diff
    if not isinstance(d1, dict):
        return {}

    # Resolve infinite recursion
    if level != -1 and level < 0:
        # treat negative levels other than -1 as 0 depth
        level = 0

    result = {}
    for key, val1 in d1.items():
        if key not in d2:
            # key missing in d2: include entire value (shallow copy if dict)
            result[key] = val1.copy() if isinstance(val1, dict) else val1
            continue

        val2 = d2[key]
        # If both are dicts and we are allowed to recurse
        if isinstance(val1, dict) and isinstance(val2, dict) and (level == -1 or level > 0):
            subdiff = difference(val1, val2, level-1 if level != -1 else -1)
            if subdiff:
                result[key] = subdiff
        else:
            # For non-dict or different types or no recursion depth left
            if val1 != val2:
                result[key] = val1.copy() if isinstance(val1, dict) else val1

    return result
<|return|>

def _validate_labels(labels):
    """
    Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from django.core.exceptions import ValidationError

    errors = []

    # Regular expressions for labels keys and values.
    key_pattern = re.compile(r'^[-.\w]+$')
    value_pattern = re.compile(r'^[-.\w]+$')

    for k, v in labels.items():
        # Validate key: must be string or bytes
        if not isinstance(k, (str, bytes)):
            errors.append({str(k): 'expected string or bytes-like object'})
        else:
            if not key_pattern.match(k):
                errors.append({
                    k: f"Label key '{k}' does not match the regex [{key_pattern.pattern}]"
                })

        # Validate value: must be string or bytes
        if isinstance(v, dict):
            # If the value is a dictionary we skip nested validation for now.
            # This can be extended if nested labels are expected.
            continue

        if not isinstance(v, (str, bytes)):
            errors.append({str(v): 'expected string or bytes-like object'})
        else:
            if not value_pattern.match(v):
                errors.append({
                    v: f"Label value '{v}' does not match the regex [{value_pattern.pattern}]"
                })

    if errors:
        raise ValidationError(errors)<|return|>

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    def _process(value, is_first_level):
        if isinstance(value, dict):
            new_dict = {}
            for k, v in value.items():
                new_dict[k] = _process(v, False)
            # If this is the top level and we need to keep identifying fields,
            # copy them from the original manifest. The keys are hard‑coded
            # for common Kubernetes resources.
            if is_first_level:
                # Common identifying fields
                for field in ("kind", "apiVersion"):
                    if field in value and new_dict.get(field) is None:
                        new_dict[field] = value[field]
                metadata = value.get("metadata", {})
                for subfield in ("name", "namespace", "labels", "annotations"):
                    if subfield in metadata and new_dict.get("metadata", {}).get(subfield) is None:
                        # Ensure metadata dict exists
                        if "metadata" not in new_dict:
                            new_dict["metadata"] = {}
                        new_dict["metadata"][subfield] = metadata[subfield]
            return new_dict
        elif isinstance(value, (list, tuple)):
            # Process each element
            new_list = []
            for elem in value:
                if isinstance(elem, (dict, list, tuple)):
                    new_list.append(_process(elem, False))
                else:
                    new_list.append(None)
            return new_list
        else:
            return None

    return _process(manifest_dict, first_level)<|return|>

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
