    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """

    # Fields that identify a Kubernetes resource – their values are preserved at the top level
    _identifying_keys = {"apiVersion", "kind", "metadata", "name", "namespace"}

    result = {}

    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Recurse into nested dictionaries; only the top level uses first_level=True
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Preserve list structure; recurse on dict items, replace primitives with None
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item, first_level=False))
                elif isinstance(item, list):
                    # Nested lists are unlikely but handled for completeness
                    new_list.append(
                        [
                            generate_default_observer_schema_dict(sub, first_level=False)
                            if isinstance(sub, dict)
                            else None
                            for sub in item
                        ]
                    )
                else:
                    new_list.append(None)
            result[key] = new_list
        else:
            # Primitive value – keep it only if we're at the top level and key is identifying
            result[key] = value if first_level and key in _identifying_keys else None

    return result
<|return|>

