    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    # Ensure the list is long enough to hold all observed elements
    while len(last_applied_manifest) < len(observer_schema):
        last_applied_manifest.append(None)

    for idx, schema_item in enumerate(observer_schema):
        # Grab the corresponding element from the response, if it exists
        resp_item = response[idx] if idx < len(response) else None

        # If the target slot is empty or None, initialize it
        if idx >= len(last_applied_manifest) or last_applied_manifest[idx] is None:
            if isinstance(schema_item, dict):
                # Nested dictionary case: initialise dict and recurse
                last_applied_manifest[idx] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[idx], schema_item, resp_item
                )
            elif isinstance(schema_item, list):
                # Nested list case: initialise list and recurse
                last_applied_manifest[idx] = []
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[idx], schema_item, resp_item
                )
            else:
                # Primitive value: simply copy if available, else keep None
                last_applied_manifest[idx] = resp_item
        else:
            # Slot already populated – we may still need to fill nested sub‑structures
            if isinstance(schema_item, dict):
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[idx], schema_item, resp_item
                )
            elif isinstance(schema_item, list):
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[idx], schema_item, resp_item
                )
    # The function mutates last_applied_manifest in place; nothing to return.<|return|>

