                last_applied_manifest[key] = response[key]<|return|>

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for key, schema in observer_schema.items():
        if key not in response:
            raise KeyError(f"Observed field {key!r} missing in response")

        # Initialize value in last_applied_manifest if absent
        if key not in last_applied_manifest:
            # Determine placeholder based on schema type
            if isinstance(schema, dict):
                last_applied_manifest[key] = {}
            elif isinstance(schema, list):
                # Assume list schema contains a single placeholder element
                last_applied_manifest[key] = []
            else:
                # For scalar or other types, copy the response value
                last_applied_manifest[key] = response[key]

        # Recurse into nested structures
        if isinstance(schema, dict):
            # Ensure nested dict exists
            if not isinstance(last_applied_manifest[key], dict):
                last_applied_manifest[key] = {}
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], schema, response[key]
            )
        elif isinstance(schema, list):
            # Use the list helper for list fields
            if not isinstance(last_applied_manifest[key], list):
                last_applied_manifest[key] = []
            # Assume the list schema contains one item schema
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[key], schema[0], response[key]
            )
    return last_applied_manifest<|return|>

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for key, schema in observer_schema.items():
        if key not in response:
            raise KeyError(f"Observed field {key!r} not present in response")
        if isinstance(schema, dict):
            # Nested dictionary: ensure nested dict exists and recurse
            if key not in last_applied_manifest or not isinstance(last_applied_manifest[key], dict):
                last_applied_manifest[key] = {}
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], schema, response[key]
            )
        else:
            # Leaf field: add if not already present
            if key not in last_applied_manifest:
                last_applied_manifest[key] = response[key]
    return last_applied_manifest<|return|>

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the application spec has a place to hold observer schemas
    observer_schema = getattr(app.spec, "observer_schema", {})
    if observer_schema is None:
        observer_schema = {}
    default_schema = {}

    # Iterate over all resources in the manifest
    for res in getattr(app.spec, "manifest", []):
        kind = res.get("kind")
        if not kind:
            continue

        # Skip if a custom observer schema already exists for this kind
        if kind in observer_schema:
            continue

        # Build a minimal default schema. For now we return an empty dict.
        # This can be extended to include default fields extracted from the resource.
        default_schema[kind] = {}

    return default_schema<|return|>

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Retrieve the manifest from the application spec
    spec = getattr(app, 'spec', None)
    if not spec:
        return

    manifest = getattr(spec, 'manifest', None)
    if not manifest:
        return

    # The manifest is expected to contain a list of resources under the key
    # ``resources``.  We iterate over them and fill in a generic observer schema
    # whenever a custom one is missing.
    resources = manifest.get('resources', [])
    if not isinstance(resources, list):
        return

    # A minimal, generic observer schema that captures the common topology of a
    # Kubernetes object.  Concrete projects may replace this with something more
    # specific.
    default_schema = {
        'type': 'object',
        'properties': {
            'metadata': {
                'type': 'object',
                'properties': {
                    'name': {'type': 'string'},
                    'namespace': {'type': 'string'},
                },
                'required': ['name'],
            },
            'status': {'type': 'object', 'additionalProperties': True},
            'spec': {'type': 'object', 'additionalProperties': True},
        },
    }

    for resource in resources:
        if not isinstance(resource, dict):
            continue
        # Skip resources that already provide an observer schema explicitly.
        if resource.get('observer_schema') or resource.get('custom_observer_schema'):
            continue
        # Attach the default schema, deep copying to avoid same reference among
        # resources if mutated later.
        resource['observer_schema'] = copy.deepcopy(default_schema)
        # Preserve the original schema for backward compatibility.
        resource.setdefault('custom_observer_schema', None)<|return|>

def format(
        self,
        sql: AnyStr,
        params: Union[Dict[Union[str, int], Any], Sequence[Any]],
    ) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.
    """
    # Preserve type of sql (str or bytes)
    is_bytes = isinstance(sql, (bytes, bytearray))
    if is_bytes:
        pattern = re.compile(br"%\(([^)]+)\)[sd]|b':([a-zA-Z_][a-zA-Z0-9_]*)'")
    else:
        pattern = re.compile(r"%\(([^)]+)\)[sd]|:([a-zA-Z_][a-zA-Z0-9_]*)")

    in_style = getattr(self.SQLParams, "in_style", None)

    # If the in style is ordinal (e.g., %s or ?), just return as is
    if in_style in ("ordinal", "qmark", "numeric"):
        return (sql, params)

    # For named styles, we need to replace each name with a positional placeholder
    if isinstance(params, Mapping):
        order = []
        def repl(match):
            name = match.group(1) or match.group(2)
            if name not in params:
                raise KeyError(f"Parameter {name!r} not found in input parameters")
            order.append(params[name])
            return "?" if not is_bytes else b"?"
        formatted_sql = pattern.sub(repl, sql)
        return (formatted_sql, order)

    # If params are a sequence (maybe ordinal), just return unchanged
    return (sql, params)<|return|>

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # If path is empty or None, consider invalid
        if not path:
            return False

        # Normalise the path to a string if it supports string conversion
        try:
            path_str = str(path)
        except Exception:
            path_str = path

        # Check that the path exists and is a directory
        if not os.path.isdir(path_str):
            return False

        # Look for typical OCFL object files.  OCFL objects normally
        # contain a manifest file (JSON or text) and optionally an
        # ocfl version marker.
        manifest_candidates = ["manifest.json", "manifest.txt"]
        for name in manifest_candidates:
            if os.path.isfile(os.path.join(path_str, name)):
                return True

        # Some repositories keep an ``ocfl_version`` file at the root,
        # which is also a quick sanity check.
        if os.path.isfile(os.path.join(path_str, "ocfl_version")):
            return True

        # If none of the expected files are present, treat as invalid
        return False
    except Exception:
        # Any error during validation is treated as a failure.
        return False<|return|>

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Import needed modules lazily to avoid global imports
    import os
    try:
        import json
    except Exception:
        # If json module cannot be imported, fail validation
        return False

    # Resolve pyfs path if provided
    try:
        # pyfs path objects may expose fs and path attributes
        if hasattr(path, 'getsyspath'):
            # Directly get underlying filesystem path
            root = path.getsyspath()
        elif hasattr(path, 'fs') and hasattr(path, 'path'):
            root = os.path.join(path.fs.getsyspath(), path.path)
        else:
            root = path
    except Exception:
        root = path

    # Basic existence and type checks
    if not root:
        return False
    if not os.path.isdir(root):
        return False

    # OCFL objects must contain a manifest.json file
    manifest_path = os.path.join(root, 'manifest.json')
    if not os.path.isfile(manifest_path):
        return False

    # Attempt to read and parse the manifest; failure indicates
    # an invalid or corrupted OCFL repository
    try:
        with open(manifest_path, 'r', encoding='utf-8') as f:
            json.load(f)
    except Exception:
        return False

    # If all checks pass, consider the OCFL object valid
    return True<|return|>

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Basic sanity checks
    if not path:
        return False
    try:
        import os
        # If path is a directory or a file that represents an OCFL object root.
        if os.path.isdir(path):
            # Common marker for an OCFL root is a ".ocfl-root" file
            root_file = os.path.join(path, ".ocfl-root")
            if os.path.isfile(root_file):
                return True
            # Attempt to load using the OCFL library if available
            try:
                from ocfl import OCFLObject  # type: ignore
                obj = OCFLObject.from_path(path)
                # The OCFL library may provide a verify/validate method
                if hasattr(obj, "is_valid") and obj.is_valid():
                    return True
                if hasattr(obj, "validate") and obj.validate():
                    return True
            except Exception:
                pass
        else:
            # If it is a file, it might be the root or a pyfs root
            # Just return True if the path exists
            return True
    except Exception:
        # Any exception during validation should result in False
        return False
    return False<|return|>

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Determine if path is a pyfs root (has listdir method)
        if hasattr(path, "listdir"):
            # Using pyfilesystem interface
            # In a pyfs root, listdir('/') should return entries in the root
            root_entries = path.listdir("/")
            if ".ocfl-layout" not in root_entries:
                return False
            return True
        else:
            # Treat path as a filesystem path
            if not os.path.isdir(path):
                return False
            if not os.path.isfile(os.path.join(path, ".ocfl-layout")):
                return False
            return True
    except Exception:
        # Any unexpected error is treated as invalid
        return False<|return|>

