def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        if not isinstance(inventory, dict):
            raise ArgumentError('inventory', 'inventory must be a dictionary')

        spec_version = self.spec_version

        if extract_spec_version:
            spec_type = inventory.get('type')
            if isinstance(spec_type, str):
                # try to parse version from a string like 'spec:1.0' or just '1.0'
                if ':' in spec_type:
                    _, version_candidate = spec_type.split(':', 1)
                    version_candidate = version_candidate.strip()
                    if version_candidate:
                        spec_version = version_candidate
                else:
                    spec_version = spec_type.strip()

        validator = self._get_validator_for_version(spec_version)
        validator.validate(inventory)

        return inventory<|return|>

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Extract the list of digests that should be used from the manifest
    needed_digests = {d for _, d in manifest_files}
    # Detect any digests marked as used that aren't present in the manifest
    unused_digests = set(digests_used) - needed_digests
    if unused_digests:
        raise ValueError(f"Usage references digests not present in manifest: {sorted(unused_digests)}")
    # Detect any digests required by the manifest but not marked as used
    missing_digests = needed_digests - set(digests_used)
    if missing_digests:
        raise ValueError(f"Digests required by manifest but not used: {sorted(missing_digests)}")
    return True<|return|>

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    required = set()
    for entry in manifest_files:
        if isinstance(entry, dict):
            digest = entry.get('digest')
        else:
            digest = getattr(entry, 'digest', None)
        if digest:
            required.add(digest)

    used = set(digests_used)

    missing = required - used
    if missing:
        raise ValueError(f"Digests in manifest not used: {sorted(missing)}")

    unused = used - required
    if unused:
        raise ValueError(f"Digests used but not present in manifest: {sorted(unused)}")<|return|>

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    used_digests = set(digests_used)
    missing_files = []

    # Assuming manifest_files is a mapping of filename -> digest
    for filename, digest in manifest_files.items():
        if digest not in used_digests:
            missing_files.append(filename)

    if missing_files:
        raise ValueError(
            f"Missing digests for files: {', '.join(missing_files)}"
        )<|return|>

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is an InventoryValidator instance
    try:
        from .inventory_validator import InventoryValidator
    except Exception:
        # Fallback: assume any object with an `inventory` attribute is acceptable
        InventoryValidator = object

    if not isinstance(prior, InventoryValidator):
        raise TypeError(
            "prior must be an InventoryValidator instance, got: {0!r}".format(prior)
        )

    # Both inventories must contain the same set of keys
    self_keys = set(getattr(self, "inventory", {}))
    prior_keys = set(getattr(prior, "inventory", {}))
    if self_keys != prior_keys:
        missing = prior_keys - self_keys
        extra = self_keys - prior_keys
        msg_parts = []
        if missing:
            msg_parts.append("missing keys in current inventory: {0}".format(", ".join(sorted(missing))))
        if extra:
            msg_parts.append("extra keys in current inventory: {0}".format(", ".join(sorted(extra))))
        raise ValueError("Inventory key mismatch: " + "; ".join(msg_parts))

    # Verify that each prior version is not newer than the corresponding current version
    for key in self_keys:
        curr_version = self.inventory[key]
        prior_version = prior.inventory[key]
        # Assuming version objects support comparison; fallback to string comparison
        try:
            if prior_version > curr_version:
                raise ValueError(
                    f"Prior version ({prior_version}) for key '{key}' is newer than current version ({curr_version})"
                )
        except Exception:
            # If comparison fails (e.g., types differ), compare string representations
            if str(prior_version) > str(curr_version):
                raise ValueError(
                    f"Prior version ({prior_version}) for key '{key}' is newer than current version ({curr_version})"
                )
    # If all checks pass, simply return None (validation succeeded)
    return None<|return|>

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Make sure the object passed in is the correct type
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator instance")

    # Verify that both inventories have a comparable version attribute
    if not hasattr(self, "version") or not hasattr(prior, "version"):
        raise AttributeError("both inventories must define a 'version' attribute")
    if prior.version >= self.version:
        raise ValueError(f"Prior version ({prior.version}) must be older than {self.version}")

    # Ensure the species sets match exactly
    if set(self.species) != set(prior.species):
        raise ValueError("Species lists differ between the current and prior inventories")

    # Ensure the reaction sets match exactly
    if set(self.reactions) != set(prior.reactions):
        raise ValueError("Reaction lists differ between the current and prior inventories")

    # If stoichiometry is stored as a matrix/list, ensure it is identical
    try:
        # numpy arrays – use array_equal for strict comparison
        if hasattr(self, "stoichiometry") and hasattr(prior, "stoichiometry"):
            if self.stoichiometry.shape != prior.stoichiometry.shape:
                raise ValueError("Stoichiometry matrices have different shapes")
            if not np.array_equal(self.stoichiometry, prior.stoichiometry):
                raise ValueError("Stoichiometry matrices differ between inventories")
    except Exception:
        # Fallback: compare element-wise if numpy not available
        if getattr(self, "stoichiometry", None) != getattr(prior, "stoichiometry", None):
            raise ValueError("Stoichiometry matrices differ between inventories")

    # All checks passed
    return True<|return|>

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.
    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the expected type
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator instance")

    # Both inventories must expose a version attribute for comparison
    if not hasattr(self, "version") or not hasattr(prior, "version"):
        raise AttributeError(
            "Both inventories must have a 'version' attribute for comparison"
        )
    if prior.version >= self.version:
        raise ValueError(
            f"Prior inventory version ({prior.version}) must be older than "
            f"current inventory version ({self.version})"
        )

    # Determine where the inventory items are stored; typical names are
    # '_items', 'items', 'inventory', or 'catalog'.  Pick the first that exists.
    for name in ("_items", "items", "inventory", "catalog"):
        if hasattr(self, name) and hasattr(prior, name):
            self_items = getattr(self, name)
            prior_items = getattr(prior, name)
            break
    else:
        raise AttributeError(
            "Neither inventory has a recognised items attribute "
            "('_items', 'items', 'inventory', or 'catalog')"
        )

    # Ensure the prior inventory items are present in the current inventory
    # with unchanged types.
    missing = []
    type_mismatch = []
    for key, prior_obj in prior_items.items():
        if key not in self_items:
            missing.append(key)
        else:
            self_obj = self_items[key]
            if type(self_obj) is not type(prior_obj):
                type_mismatch.append((key, type(prior_obj).__name__, type(self_obj).__name__))

    if missing:
        raise ValueError(
            f"The following items from the prior inventory are missing in the current inventory: "
            f"{', '.join(missing)}"
        )
    if type_mismatch:
        msgs = [
            f"'{k}' changed type from {old} to {new}"
            for k, old, new in type_mismatch
        ]
        raise ValueError(
            "Type mismatch between prior and current inventory items: "
            + "; ".join(msgs)
        )

    # If the inventory items themselves contain nested inventories, one could
    # recurse here, but for the top‑level validation this is sufficient.
    return None
<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    import re

    def _parse_version(v):
        """Convert a version string to a comparable tuple of integers."""
        return tuple(int(p) for p in re.split(r'[^0-9]', str(v)) if p)

    if version is not None:
        try:
            ver_target = _parse_version(version)
        except Exception:
            # Fall back to string comparison if parsing fails
            ver_target = str(version)
    else:
        ver_target = None

    result = {}
    for logical_path, data in inventory.items():
        # Determine the mapping from versions to file sets
        if isinstance(data, dict):
            if "versions" in data and isinstance(data["versions"], dict):
                version_map = data["versions"]
            else:
                version_map = data
        else:
            continue

        files_set = set()
        for ver_key, files in version_map.items():
            # Normalize the files list to a set
            if isinstance(files, (list, tuple)):
                files = set(files)
            elif not isinstance(files, set):
                files = {files}

            # Decide whether to include this version's files
            if ver_target is None:
                include = True
            else:
                try:
                    ver_key_parsed = _parse_version(ver_key)
                    include = ver_key_parsed >= ver_target
                except Exception:
                    # If parsing fails, fall back to string comparison
                    include = str(ver_key) >= str(ver_target)

            if include:
                files_set.update(files)

        result[logical_path] = files_set
    return result<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    result = {}
    for logical_path, version_map in inventory.items():
        # Expected structure: version_map is a dict mapping version strings to file paths
        files = set()
        for ver, file_path in version_map.items():
            # Include the file for the requested version, plus any later versions
            if ver == version or ver > version:
                files.add(file_path)
        if files:
            result[logical_path] = files
    return result<|return|>

