def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    packages = {}
    abs_folder = os.path.abspath(folder)

    # First pass: find all XML files and their basenames
    for root, _, files in os.walk(abs_folder):
        for filename in files:
            if filename.lower().endswith('.xml'):
                base = os.path.splitext(filename)[0]
                xml_path = os.path.join(root, filename)
                packages[base] = {
                    'xml': xml_path,
                    'files': []
                }

    # Second pass: associate all files with the same base (if XML exists)
    for root, _, files in os.walk(abs_folder):
        for filename in files:
            base = os.path.splitext(filename)[0]
            if base in packages:
                file_path = os.path.join(root, filename)
                # Avoid adding the XML file again in the list
                if file_path != packages[base]['xml']:
                    packages[base]['files'].append(file_path)

    return packages
<|return|>

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    package_data = {}
    for entry in os.listdir(folder):
        full_path = os.path.join(folder, entry)
        if not os.path.isfile(full_path):
            continue
        base, ext = os.path.splitext(entry)
        if base not in package_data:
            package_data[base] = {'xml': None, 'files': []}
        if ext.lower() == '.xml':
            package_data[base]['xml'] = full_path
        else:
            package_data[base]['files'].append(full_path)
    return package_data<|return|>

