def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        Mapping of XML basename to a dict of related file names and their bytes data.
    """
    import zipfile, os

    packages = {}

    with zipfile.ZipFile(zip_path, 'r') as zf:
        # Identify all XML files to establish the package basenames
        xml_entries = {}
        for info in zf.infolist():
            if info.is_dir():
                continue
            base, ext = os.path.splitext(os.path.basename(info.filename))
            if ext.lower() == '.xml':
                xml_entries[base] = info.filename

        # Initialize the result dict with each base
        for base in xml_entries:
            packages[base] = {}

        # Collect all files that belong to these packages
        for info in zf.infolist():
            if info.is_dir():
                continue
            base_name = os.path.splitext(os.path.basename(info.filename))[0]
            if base_name in xml_entries:
                packages[base_name][info.filename] = zf.read(info.filename)

    return packages<|return|>

