        indent_str = ' ' * indent
    else:
        indent_str = str(indent)
    # Start with class name and id for uniqueness
    header = f'{self.__class__.__name__} object at {hex(id(self))}'
    if debug:
        header += '\n' + 'Debug: ' + repr(vars(self))
    lines = [header]
    # Get attributes sorted alphabetically
    attrs = sorted(vars(self).keys())
    for key in attrs:
        value = getattr(self, key)
        # Recursively pretty print if the object has its own pretty method and is not self
        if hasattr(value, 'pretty') and callable(value.pretty) and value is not self:
            try:
                val_repr = value.pretty(indent=indent + 4, debug=debug)
            except Exception:
                val_repr = repr(value)
        else:
            val_repr = repr(value)
        # Split long value representation into multiple lines if needed
        val_lines = val_repr.splitlines()
        if len(val_lines) == 1:
            lines.append(f'{indent_str}    {key} = {val_lines[0]}')
        else:
            lines.append(f'{indent_str}    {key} =')
            for vl in val_lines:
                lines.append(f'{indent_str}        {vl}')
    return '\n'.join(lines)<|return|>

