def get_versions():
    """Get version information or return default if unable to do so."""
    info = {}
    try:
        import pkgutil
        import importlib
        for _, modname, _ in pkgutil.iter_modules():
            try:
                mod = importlib.import_module(modname)
                # Try common version attributes
                ver = getattr(mod, "__version__", None)
                if ver is None:
                    ver = getattr(mod, "VERSION", None)
                if ver is not None:
                    info[modname] = str(ver)
            except Exception:
                # Skip modules that cannot be imported or lack version info
                continue
    except Exception:
        # If any global failure occurs, return default
        return {"default": "unknown"}
    # Return gathered info or a default if nothing found
    return info or {"default": "unknown"}<|return|>

