def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Default to plain text if style is not specified
    style = style or 'plain'

    if not isinstance(pieces, (list, tuple)):
        raise TypeError('pieces must be a list or tuple')

    # Ensure we have up to five components: major, minor, patch, prerelease, build
    parts = list(pieces) + [None] * (5 - len(pieces))
    major, minor, patch, prerelease, build = parts[:5]

    def _s(v):
        return '' if v is None else str(v)

    base = '.'.join(filter(None, [_s(major), _s(minor), _s(patch)]))
    if prerelease:
        base += f'-{prerelease}'
    if build:
        base += f'+{build}'

    if style == 'plain':
        return base
    elif style == 'numeric':
        try:
            m = int(major) if major is not None else 0
            n = int(minor) if minor is not None else 0
            p = int(patch) if patch is not None else 0
        except Exception:
            raise ValueError('numeric style requires integer major, minor, and patch')
        return str(m * 1_000_000 + n * 1_000 + p)
    elif style == 'major':
        return str(major)
    elif style == 'minor':
        return f'{major}.{minor}'
    elif style == 'patch':
        return f'{major}.{minor}.{patch}'
    else:
        raise ValueError(f'Unknown style: {style}')<|return|>

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Helper render functions for various formats
    def _to_json(p):
        import json
        return json.dumps(p, indent=2)

    def _to_text(p):
        return '\n'.join(str(item) for item in p)

    def _to_html(p):
        items = ''.join(f'  <li>{item}</li>\n' for item in p)
        return f'<ul>\n{items}</ul>'

    def _to_csv(p):
        import csv
        from io import StringIO
        output = StringIO()
        writer = csv.writer(output)
        writer.writerow(['Item'])
        for item in p:
            writer.writerow([item])
        return output.getvalue()

    # Map style identifiers to rendering functions
    renderers = {
        'json': _to_json,
        'text': _to_text,
        'html': _to_html,
        'csv': _to_csv,
    }

    # Normalise style key and fetch renderer
    renderer = renderers.get(style.lower().strip())
    if renderer is None:
        raise ValueError(f"Unsupported rendering style: {style!r}")

    # Render and return the result
    return renderer(pieces)<|return|>

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Ensure pieces is iterable; if a single string or object, treat as list
    if not hasattr(pieces, "__iter__") or isinstance(pieces, (str, bytes)):
        pieces = [pieces]

    # Convert each piece to string
    strs = [str(p) for p in pieces]

    if style == "plain":
        # Join with pipe separators and trim whitespace
        return " | ".join(s.strip() for s in strs)

    elif style == "html":
        # Wrap each piece in a code span for safe display
        return " ".join(f'<code>{s}</code>' for s in strs)

    elif style == "json":
        import json
        return json.dumps(strs, ensure_ascii=False)

    elif style == "xml":
        # Simple XML enclosure: <piece>content</piece>
        return "<pieces>" + "".join(f"<piece>{s}</piece>" for s in strs) + "</pieces>"

    else:
        raise ValueError(f"Unsupported style: {style}")<|return|>

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Extract pieces whether they are a dict or an object with attributes
    def _get(key, default=0):
        if isinstance(pieces, dict):
            return str(pieces.get(key, default))
        return str(getattr(pieces, key, default))

    major = _get('major')
    minor = _get('minor')
    patch = _get('patch')
    prerelease = _get('prerelease', '')
    build = _get('build', '')

    # Helper to build version string
    def _full():
        version = f"{major}.{minor}.{patch}"
        if prerelease:
            version += f"-{prerelease}"
        if build:
            version += f"+{build}"
        return version

    if style == 'major':
        return major
    if style == 'minor':
        return f"{major}.{minor}"
    if style == 'patch':
        return f"{major}.{minor}.{patch}"
    if style == 'short':
        return f"{major}.{minor}.{patch}"
    if style == 'full' or style is None:
        return _full()
    raise ValueError(f"Unknown style '{style}'")<|return|>

