    # Build the full command list
    if isinstance(commands, (list, tuple)):
        full_cmd = list(commands) + list(args)
    else:
        full_cmd = [commands] + list(args)

    if verbose:
        print("Running command:", " ".join(full_cmd))

    # Set up stderr handling
    stderr_target = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_target,
            text=True,
            check=True,
        )
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(
            f"Command '{' '.join(full_cmd)}' failed with exit code {exc.returncode}"
        ) from exc

    return result.stdout<|return|>

