def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        num_objects = 0
        good_objects = 0
        validation_warnings = []

        # Retrieve all objects that belong to the hierarchy.
        # The exact source may differ; try common patterns.
        if hasattr(self, "objects") and isinstance(self.objects, (list, tuple)):
            objects = self.objects
        elif hasattr(self, "root"):
            # Assume the root has an iterator that yields all objects.
            try:
                objects = list(self.root.iter_objects())
            except Exception:
                objects = []
        else:
            objects = []

        for obj in objects:
            num_objects += 1
            valid = True

            # Object-level validation
            if validate_objects:
                try:
                    if hasattr(obj, "validate"):
                        valid = bool(obj.validate())
                    else:
                        # If no validate method, assume the object is valid.
                        valid = True
                except Exception as e:
                    valid = False
                    if show_warnings:
                        validation_warnings.append(
                            f"Object {getattr(obj, 'id', obj)} failed validation: {e}"
                        )

            if not valid:
                continue

            # Digest / checksum validation
            if check_digests:
                try:
                    if hasattr(obj, "compute_digest") and hasattr(obj, "digest"):
                        computed = obj.compute_digest()
                        if computed != obj.digest:
                            valid = False
                            if show_warnings:
                                validation_warnings.append(
                                    f"Digest mismatch on object {getattr(obj, 'id', obj)}"
                                )
                except Exception as e:
                    valid = False
                    if show_warnings:
                        validation_warnings.append(
                            f"Error checking digest for object {getattr(obj, 'id', obj)}: {e}"
                        )

            if valid:
                good_objects += 1

        # Store warnings for later inspection if needed
        self._validation_warnings = validation_warnings

        return num_objects, good_objects<|return|>

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        # Counters for overall objects and those validated as good
        num_objects = 0
        good_objects = 0

        # Helper for digest comparison; in real code this might use hashlib
        def _compute_digest(obj):
            # Simple deterministic placeholder digest
            return str(hash(frozenset(obj.items())))

        # Iterate over objects in the hierarchy.  This example assumes the
        # instance has a `_iter_objects` generator that yields dictionary
        # representations of each object.  Subclasses may override this method
        # to traverse a database, a filesystem, or another storage location.
        for obj in getattr(self, "_iter_objects", lambda: [])():
            num_objects += 1
            obj_valid = True

            # Optional object‑specific validation
            if validate_objects:
                # If the object provides an `is_valid` method, use that.
                # Otherwise use a generic `valid` key.
                if hasattr(obj, "is_valid") and callable(obj.is_valid):
                    try:
                        obj_valid = bool(obj.is_valid())
                    except Exception as exc:
                        obj_valid = False
                        if show_warnings:
                            print(f"Warning: Exception during is_valid() on {obj}: {exc}")
                else:
                    obj_valid = bool(obj.get("valid", True))

                # If an explicit digest comparison is requested, perform it.
                if obj_valid and check_digests and "digest" in obj:
                    try:
                        computed = _compute_digest(obj)
                        if computed != obj["digest"]:
                            obj_valid = False
                            if show_warnings:
                                print(f"Warning: Digest mismatch for {obj}")
                    except Exception as exc:
                        obj_valid = False
                        if show_warnings:
                            print(f"Warning: Exception during digest validation on {obj}: {exc}")

            if obj_valid:
                good_objects += 1

        return num_objects, good_objects<|return|>

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Retrieve the objects that make up the hierarchy.  The implementation
    # attempts to be tolerant of different attribute names that may be
    # used by subclasses or legacy code.
    objects = getattr(self, 'hierarchy_objects', None) or getattr(self, 'objects', None)
    if objects is None:
        # Fall back to a method that might provide the objects.
        objects = getattr(self, 'get_root_objects', lambda: [])()
    if not isinstance(objects, (list, tuple)):
        # Unexpected container, cannot proceed.
        raise TypeError(f'Expected a list or tuple of objects, got {type(objects)}')

    num_objects = 0
    good_objects = 0

    for obj in objects:
        num_objects += 1
        valid = True

        if validate_objects:
            try:
                # Many objects may expose a validate() method that
                # performs internal checks.
                validate_method = getattr(obj, 'validate', None)
                if callable(validate_method):
                    validate_method()
                else:
                    # If no explicit validate, assume object type is correct.
                    pass
            except Exception as exc:
                valid = False
                if show_warnings:
                    print(f"[validate_hierarchy] Validation failed for {obj!r}: {exc}")

        if check_digests and valid:
            try:
                # Digest checks are optional and may be performed by a method
                # named 'check_digest' or 'validate_digest'.
                digest_method = getattr(obj, 'check_digest', None) or getattr(obj, 'validate_digest', None)
                if callable(digest_method):
                    if not digest_method():
                        valid = False
                        if show_warnings:
                            print(f"[validate_hierarchy] Digest mismatch for {obj!r}")
                else:
                    # No digest method: treat as valid.
                    pass
            except Exception as exc:
                valid = False
                if show_warnings:
                    print(f"[validate_hierarchy] Digest check failed for {obj!r}: {exc}")

        if valid:
            good_objects += 1
        elif show_warnings:
            print(f"[validate_hierarchy] Object {obj!r} failed validation checks.")

    return num_objects, good_objects<|return|>

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    import os
    import hashlib

    num_objects = 0
    good_objects = 0

    # Determine the root of the storage hierarchy; this attribute should be
    # defined on the instance that owns this method.
    root = getattr(self, 'storage_root', None)
    if root is None:
        raise AttributeError("Instance does not have a 'storage_root' attribute.")

    for dirpath, dirnames, filenames in os.walk(root):
        for filename in filenames:
            num_objects += 1
            full_path = os.path.join(dirpath, filename)
            valid = True

            # Basic object validation: file must be readable.
            if validate_objects:
                try:
                    with open(full_path, 'rb') as f:
                        f.read(1)  # attempt to read first byte
                except Exception as e:
                    valid = False
                    if show_warnings:
                        print(f"Validation error for {full_path}: {e}")

            # Digest (checksum) validation if requested.
            if check_digests:
                # Assumes a separate .sha256 file next to each object containing the expected hash.
                sum_path = f"{full_path}.sha256"
                if os.path.exists(sum_path):
                    try:
                        with open(full_path, 'rb') as f:
                            actual_hash = hashlib.sha256(f.read()).hexdigest()
                        with open(sum_path, 'r') as sf:
                            expected_hash = sf.read().strip()
                        if actual_hash != expected_hash:
                            valid = False
                            if show_warnings:
                                print(f"Digest mismatch for {full_path}: expected {expected_hash}, got {actual_hash}")
                    except Exception as e:
                        valid = False
                        if show_warnings:
                            print(f"Digest verification failed for {full_path}: {e}")
                else:
                    if show_warnings:
                        print(f"Missing digest file for {full_path}: expected {sum_path}")

            if valid:
                good_objects += 1

    return num_objects, good_objects<|return|>

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    import os
    import hashlib

    root_path = getattr(self, 'root_path', None) or getattr(self, '_root', None)
    if not root_path or not os.path.isdir(root_path):
        raise RuntimeError('Root path is not set or does not exist.')

    num_objects = 0
    good_objects = 0

    for dirpath, dirnames, filenames in os.walk(root_path):
        for filename in filenames:
            # Skip standalone digest files
            if filename.endswith('.digest'):
                continue

            file_path = os.path.join(dirpath, filename)
            num_objects += 1
            is_good = True

            if validate_objects:
                try:
                    with open(file_path, 'rb') as f:
                        f.read()
                except Exception as exc:
                    is_good = False
                    if show_warnings:
                        print(f'Warning: cannot read {file_path}: {exc}')

            if check_digests and is_good:
                digest_file = f'{file_path}.digest'
                if os.path.isfile(digest_file):
                    try:
                        with open(digest_file, 'r') as df:
                            expected = df.read().strip()
                        hasher = hashlib.sha256()
                        with open(file_path, 'rb') as f:
                            for chunk in iter(lambda: f.read(8192), b''):
                                hasher.update(chunk)
                        actual = hasher.hexdigest()
                        if actual != expected:
                            is_good = False
                            if show_warnings:
                                print(f'Warning: digest mismatch for {file_path}')
                    except Exception as exc:
                        is_good = False
                        if show_warnings:
                            print(f'Warning: digest check failed for {file_path}: {exc}')

            if is_good:
                good_objects += 1

    return num_objects, good_objects<|return|>

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    root_path = getattr(self, "root_path", None)
    if not root_path:
        raise ValueError("Attribute 'root_path' must be set before calling initialize()")

    # Create the root directory, raising if it already exists
    try:
        os.makedirs(root_path, exist_ok=False)
    except FileExistsError:
        raise RuntimeError(f"OCFL root directory already exists at {root_path}")
    except OSError as exc:
        raise RuntimeError(f"Failed to create OCFL root directory {root_path}: {exc}") from exc

    # Create the required directory layout per OCFL spec
    required_dirs = ("objects", "index", "headings")
    for subdir in required_dirs:
        subdir_path = os.path.join(root_path, subdir)
        try:
            os.makedirs(subdir_path, exist_ok=True)
        except OSError as exc:
            raise RuntimeError(f"Failed to create subdirectory {subdir_path}: {exc}") from exc

    # Create the mandatory OCFL root version file
    version_file = os.path.join(root_path, "_ocfl_root_v1.txt")
    try:
        with open(version_file, "w", encoding="utf-8") as vf:
            vf.write("1.0\n")
