    root_mismatches = {}

    for vdir in version_dirs:
        inventory_path = os.path.join(vdir, 'inventory.json')
        try:
            with open(inventory_path, 'r') as fh:
                inv = json.load(fh)
        except FileNotFoundError:
            raise ValueError(f'Inventory file missing in version directory {vdir}')
        if not isinstance(inv, dict):
            raise ValueError(f'Inventory in {vdir} must be a dict mapping file names to digests')

        # Validate that all files from previous inventories are present
        missing = set(cumulative_inventory.keys()) - set(inv.keys())
        if missing:
            raise ValueError(f'{vdir} inventory is missing files from previous inventories: {", ".join(sorted(missing))}')

        # Validate that digests are consistent with previous versions
        for file, digest in inv.items():
            prev_digest = cumulative_inventory.get(file)
            if prev_digest is not None and digest != prev_digest:
                root_mismatches.setdefault(vdir, []).append(file)

        # Validate digests against the root inventory, if present
        if hasattr(self, 'root_inventory') and isinstance(self.root_inventory, dict):
