                if root_digest and digest != root_digest:
                    root_mismatches.setdefault(vdir, []).append(file)

        # Update the cumulative inventory for the next iteration
        cumulative_inventory = inv

    self.mismatched_digests = root_mismatches
    return root_mismatches<|return|>

