    Also keep a record of any content digests different from those in the
    root inventory so that we can also check them when validating the
    content.

    version_dirs is an array of version directory names and is assumed to
    be in version sequence (1, 2, 3...).
    """
    # Assume the first directory contains the root inventory
    root_inv = {}
    if not version_dirs:
        raise ValueError("No version directories provided")

    # Helper to load an inventory from a directory
    def load_inventory(path):
        # Try JSON first, then a simple text format (path digest)
        inv = {}
        json_path = path / "inventory.json"
        txt_path = path / "inventory.txt"
        if json_path.exists():
            with json_path.open("r", encoding="utf-8") as fp:
                inv = json.load(fp)
        elif txt_path.exists():
            with txt_path.open("r", encoding="utf-8") as fp:
                for line in fp:
                    line = line.strip()
                    if not line or line.startswith("#"):
                        continue
                    try:
                        p, d = line.split(None, 1)
                    except ValueError:
                        continue
                    inv[p] = d
        else:
            # No inventory file found; treat as empty
            inv = {}
        return inv

    from pathlib import Path
    prev_keys = set()
    self.different_digests = {}
    for idx, dir_name in enumerate(version_dirs):
        dir_path = Path(dir_name)
        inv = load_inventory(dir_path)

        # For the root version, remember the inventory for later checks
        if idx == 0:
            root_inv = inv.copy()

        # Ensure the inventory contains all files from previous versions
        if idx > 0:
            missing = prev_keys.difference(inv.keys())
            if missing:
                raise ValueError(
                    f"Inventory in '{dir_name}' missing expected files from "
                    f"previous versions: {sorted(missing)}"
                )

        # Record any differing digests compared to the root inventory
        for rel_path, ext_digest in inv.items():
            root_digest = root_inv.get(rel_path)
            if root_digest and root_digest != ext_digest:
                self.different_digests.setdefault(rel_path, {})[dir_name] = ext_digest

        # Update the set of known keys for the next iteration
        prev_keys.update(inv.keys())
    return self <|return|>

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...)."""
    # Ensure we have a root inventory to compare against
    if not hasattr(self, "root_inventory") or self.root_inventory is None:
        raise AttributeError("self.root_inventory must be set before validating inventories")
    root_inventory = self.root_inventory

    # This dict will map item identifiers to a list of tuples describing the
    # mismatches: (version_dir, inventory_digest, reference_digest)
    self.different_digests = {}

    # Keep track of what the cumulative inventory looks like up to the
    # previous version.  Each new inventory must be a superset of the
    # previous one.
    cumulative = {}

    for idx, version_dir in enumerate(version_dirs, start=1):
        inv_path = os.path.join(version_dir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(
                f"Missing inventory.json in version directory '{version_dir}'"
            )
        try:
            with open(inv_path, "r") as f:
                current_inv = json.load(f)
        except Exception as e:
            raise ValueError(f"Could not read inventory.json in '{version_dir}': {e}")

        if not isinstance(current_inv, dict):
            raise TypeError(
                f"Inventory in '{version_dir}' must be a mapping of items to digests"
            )

        # Check that the current inventory contains all items from previous
        # inventories and record any digest differences
        for item, digest in current_inv.items():
            if item in cumulative:
                if cumulative[item] != digest:
                    self.different_digests.setdefault(
                        item, []
                    ).append((version_dir, digest, cumulative[item]))
            else:
                # New item: just record in cumulative
                pass

            # Also compare against the root inventory when applicable
            if item in root_inventory and root_inventory[item] != digest:
                self.different_digests.setdefault(
                    item, []
                ).append((version_dir, digest, root_inventory[item]))

        # Update cumulative inventory
        cumulative.update(current_inv)

    return self<|return|>

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    import re

    if not os.path.exists(path):
        return f"Path '{path}' does not exist."

    try:
        if os.path.isfile(path):
            return 'file'
        if os.path.isdir(path):
            # enumerate directory entries
            for entry in os.listdir(path):
                if re.match(r'^0=.*', entry):
                    return 'object'
            return 'root'
    except Exception as exc:
        return f"Error: {exc}"

    return f"Unknown type for path '{path}'."
