def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    if not os.path.exists(path):
        return f"path does not exist: {path}"

    # Files are simple
    if os.path.isfile(path):
        return 'file'

    if os.path.isdir(path):
        # 1. Check for a storage root: presence of an inventory file
        inventory_file = os.path.join(path, 'inventory')
        if os.path.isfile(inventory_file):
            return 'root'
        # 2. Check for object directories: a subdirectory whose name starts with "0="
        try:
            for entry in os.listdir(path):
                if entry.startswith('0=') and os.path.isdir(os.path.join(path, entry)):
                    return 'object'
        except OSError as exc:
            return f"error reading directory {path}: {exc}"

        # 3. Common case: a subdirectory called "objects" indicates a root
        if os.path.isdir(os.path.join(path, 'objects')):
            return 'root'

    # If we got here, we couldn't determine the type
    return f"unknown type for path: {path}"<|return|>

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os, re
    # Check if path exists and type
    if not os.path.exists(path):
        return f"not found: {path}"
    # If it is a file return 'file'
    if os.path.isfile(path):
        return "file"
    # If it is a directory
    if os.path.isdir(path):
        try:
            entries = os.listdir(path)
        except OSError as e:
            return f"access error: {e}"
        # Pattern for Namaste file starting with "0="
        namaste_pattern = re.compile(r"^0=")
        # Check for object-level namaste file
        for entry in entries:
            full = os.path.join(path, entry)
            if os.path.isfile(full) and namaste_pattern.match(entry):
                return "object"
        # If no namaste file in this dir, check subdirectories for object indiciation
        for entry in entries:
            full = os.path.join(path, entry)
            if os.path.isdir(full):
                try:
                    sub_entries = os.listdir(full)
                except OSError:
                    continue
                for sub in sub_entries:
                    if namaste_pattern.match(sub):
                        return "root"
        # Default: treat as root if any subdirectories exist
        if any(os.path.isdir(os.path.join(path, e)) for e in entries):
            return "root"
        # If empty directory, consider it root
        return "root"
    return f"unknown type: {path}"
