    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to merge mapping node values
    def merge_mapping_nodes(a, b):
        # a and b are expected to be MappingNode instances
        merged_pairs = merge_pairs(a.value + b.value)
        # Create a new MappingNode preserving the tag from the first node
        return type(a)(a.tag, merged_pairs)

    # Helper that merges two values according to rules
    def merge_values(a, b):
        if isinstance(a, type(b)) and isinstance(a, type(b)) and hasattr(a, 'tag') and hasattr(b, 'tag'):
            # likely both are MappingNode, but also could be other node types that support dict-like merging
            # We specifically handle MappingNode deeply
            if hasattr(a, 'value') and hasattr(b, 'value') and isinstance(a.value, list) and isinstance(b.value, list):
                # Assume MappingNode
                return merge_mapping_nodes(a, b)
        # For all other cases, last value wins
        return b

    # Merge a list of (key, value) pairs, preserving first occurrence order
    def merge_pairs(pairs):
        result = []
        key_index = {}
        for k, v in pairs:
            key_val = k.value  # ScalarNode's value is used for key comparison
            if key_val in key_index:
                idx = key_index[key_val]
                # Merge the values
                existing_key, existing_val = result[idx]
                result[idx] = (existing_key, merge_values(existing_val, v))
            else:
                # keep the original key node to preserve identity
                result.append((k, v))
                key_index[key_val] = len(result) - 1
        return result

    return merge_pairs(nodes)
