    Parameters
    ----------
    nodes : list of tuples
        Each tuple is (key_node, value_node) where key_node is a ScalarNode
        and value_node is a MappingNode or other Node.

    Returns
    -------
    list of tuples
        Merged list, with duplicate keys merged by deep‑merge of mapping
        values. For non‑mapping values, the last one wins.
    '''
    def is_mapping(node):
        """Return True if node looks like a MappingNode."""
        return hasattr(node, 'value') and isinstance(node.value, list)

    def merge_values(v1, v2):
        """Merge two value nodes."""
        if is_mapping(v1) and is_mapping(v2):
            merged_val = merge_mappings(v1.value, v2.value)
            return type(v1)(tag=v1.tag, value=merged_val)
        # Non‑mapping: last value wins
        return v2

    def merge_mappings(list1, list2):
        """Merge two lists of (key_node, value_node) tuples."""
        merged = {}
        for k_node, v_node in list1:
            merged[k_node.value] = (k_node, v_node)
        for k_node, v_node in list2:
            k = k_node.value
            if k in merged:
                old_k, old_v = merged[k]
                merged[k] = (k_node, merge_values(old_v, v_node))
            else:
                merged[k] = (k_node, v_node)
        return list(merged.values())

    final = {}
    for key_node, value_node in nodes:
        k = key_node.value
        if k in final:
            old_key, old_val = final[k]
            final[k] = (key_node, merge_values(old_val, value_node))
        else:
            final[k] = (key_node, value_node)

    return list(final.values())<|return|>

