def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    parser = argparse.ArgumentParser()
    # The parser is expected to have subparsers added elsewhere.
    try:
        subparsers_action = parser._subparsers._group_actions[0]
    except Exception:
        subparsers_action = None

    main_namespace, remaining = parser.parse_known_args(unparsed_arguments)
    result = {'global': main_namespace}

    if subparsers_action and remaining:
        first_token = remaining[0]
        if first_token in subparsers_action.choices:
            subparser = subparsers_action.choices[first_token]
            sub_namespace, _ = subparser.parse_known_args(remaining[1:])
            result[first_token] = sub_namespace

    return result<|return|>

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for k, v in d.items():
            if k in result:
                result[k] += v
            else:
                result[k] = v
    return result<|return|>

