def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''

    # Ensure url_args is a mapping (dict) or iterable of (key, value) pairs
    if isinstance(url_args, dict):
        items = url_args.items()
    else:
        try:
            items = list(url_args)
        except TypeError:
            # If it cannot be iterated, return the original URL
            return url

    for key, value in items:
        placeholder = '{' + str(key) + '}'
        url = url.replace(placeholder, str(value))

    return url<|return|>

def _replace_url_args(self, url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url or not url_args:
        return url
    # Replace `{key}` placeholders with corresponding values from url_args.
    # Keys that are not found in url_args are left unchanged.
    pattern = re.compile(r'\{([^{}]+)\}')
    def _replacer(match):
        key = match.group(1)
        if key in url_args:
            return str(url_args[key])
        return match.group(0)
    return pattern.sub(_replacer, url)<|return|>

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url or not url_args:
        return url

    import re

    pattern = re.compile(r'\{(\w+)\}')

    def _replacer(match):
        key = match.group(1)
        # Use the provided value if available, otherwise keep the placeholder
        return str(url_args.get(key, match.group(0)))

    return pattern.sub(_replacer, url)<|return|>

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''
    if not url_args:
        return url

    # Import re locally to avoid external dependencies
    import re
    pattern = r'\{([^{}]+)\}'

    def _repl(match):
        key = match.group(1)
        return str(url_args.get(key, match.group(0)))

    return re.sub(pattern, _repl, url)<|return|>

