def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("number must be non-negative")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("alphabet must contain at least two symbols for a valid base")
    if number == 0:
        s = alphabet[0]
    else:
        digits = []
        while number:
            digits.append(alphabet[number % base])
            number //= base
        s = ''.join(reversed(digits))
    if padding is not None:
        if padding < 0:
            raise ValueError("padding must be non-negative")
        pad_len = padding - len(s)
        if pad_len > 0:
            s = alphabet[0] * pad_len + s
    return s<|return|>

def int_to_string(number: int, alphabet: list, padding: int | None = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("number must be non-negative")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("alphabet must contain at least two symbols")
    # Special case for zero
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        n = number
        while n:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        digits.reverse()
    # Padding with the leading symbol of the alphabet
    if padding is not None:
        diff = padding - len(digits)
        if diff > 0:
            digits = [alphabet[0]] * diff + digits
    return "".join(digits)<|return|>

def int_to_string(number: int, alphabet: list, padding: int = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("number must be non-negative")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("alphabet must contain at least two characters")
    # Special case for zero
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        while number:
            digits.append(alphabet[number % base])
            number //= base
        digits.reverse()
    result = ''.join(digits)
    # Apply padding using the first character of the alphabet if requested
    if padding is not None:
        pad_len = padding - len(result)
        if pad_len > 0:
            result = alphabet[0] * pad_len + result
    return result<|return|>

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    def _replace(obj):
        if isinstance(obj, dict):
            new_obj = {}
            for k, v in obj.items():
                new_key = f"register_{register_number}" if k == register_value else k
                new_obj[new_key] = _replace(v)
            return new_obj
        if isinstance(obj, list):
            return [_replace(item) for item in obj]
        return obj

    return _replace(flow_params)<|return|>

