def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    stack = [cls]
    while stack:
        current = stack.pop()
        for sub in current.__subclasses__():
            if sub not in seen:
                seen.add(sub)
                stack.append(sub)
    return seen<|return|>

