def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    char_to_value = {c: i for i, c in enumerate(alphabet)}
    value = 0
    for c in string:
        if c not in char_to_value:
            raise ValueError(f"Character '{c}' not found in the alphabet")
        value = value * base + char_to_value[c]
    return value<|return|>

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    if base == 0:
        raise ValueError("Alphabet must not be empty")
    mapping = {ch: i for i, ch in enumerate(alphabet)}
    n = 0
    for ch in string:
        if ch not in mapping:
            raise ValueError(f"Character '{ch}' not in alphabet")
        n = n * base + mapping[ch]
    return n<|return|>

