def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub‑class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    # Build a mapping from child -> set of parents for the given property
    child_to_parents: Dict["Node", Set["Node"]] = {}
    for s, p, o in graph.triples((None, prop, None)):
        child_to_parents.setdefault(s, set()).add(o)

    if roots is None:
        # All nodes that appear in the graph for this property
        all_nodes: Set["Node"] = set(child_to_parents.keys()) | {
            o for parents in child_to_parents.values() for o in parents
        }
        # Roots are nodes that never appear as a child
        roots_set: Set["Node"] = all_nodes - set(child_to_parents.keys())
    else:
        # If a user supplied a set of candidate roots, filter them
        roots_set = {n for n in roots if not child_to_parents.get(n)}
    return roots_set<|return|>

