def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. 
    Return the results as a tuple of: dict of configuration filename to corresponding parsed 
    configuration, and sequence of logging.LogRecord instances containing any parse errors.
    """
    import os
    import json
    import yaml
    import toml
    import re

    config_dict = {}
    error_records = []

    def resolve_env_vars(cfg):
        if isinstance(cfg, dict):
            for k, v in cfg.items():
                cfg[k] = resolve_env_vars(v)
        elif isinstance(cfg, list):
            for i, v in enumerate(cfg):
                cfg[i] = resolve_env_vars(v)
        elif isinstance(cfg, str):
            if resolve_env:
                # Replace ${VAR} or $VAR
                def repl(match):
                    var = match.group(1)
                    return os.getenv(var, '')
                cfg = re.sub(r'\${([^}]+)}|\\$([A-Za-z_][A-Za-z0-9_]*)', lambda m: os.getenv(m.group(1) or m.group(2), ''), cfg)
        return cfg

    for fname in config_filenames:
        if not os.path.exists(fname):
            rec = logging.LogRecord('config_loader', logging.ERROR, fname, 0,
                                    f'Configuration file not found: {fname}', (), None)
            error_records.append(rec)
            continue
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                raw = f.read()
            # Try TOML, then YAML, then JSON
            cfg = None
            try:
                cfg = toml.loads(raw)
            except Exception:
                try:
                    cfg = yaml.safe_load(raw)
                except Exception:
                    try:
                        cfg = json.loads(raw)
                    except Exception as e:
                        raise e
            if cfg is None:
                raise ValueError('Unsupported configuration format')
        except Exception as e:
            rec = logging.LogRecord('config_loader', logging.ERROR, fname, 0,
                                    f'Error parsing configuration {fname}: {e}', (), e)
            error_records.append(rec)
            continue

        if overrides:
            if isinstance(cfg, dict):
                cfg.update(overrides)
        cfg = resolve_env_vars(cfg)
        config_dict[fname] = cfg

    return config_dict, error_records<|return|>

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    configs = {}
    log_records = []

    # Helper to recursively expand environment variables in values
    def _expand_env(value):
        if isinstance(value, str):
            return os.path.expandvars(value)
        if isinstance(value, dict):
            return {k: _expand_env(v) for k, v in value.items()}
        if isinstance(value, (list, tuple)):
            return type(value)(_expand_env(v) for v in value)
        return value

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                raw = f.read()
        except OSError as e:
            rec = logging.LogRecord(__name__, logging.ERROR, fname, 0,
                                    f"Could not open {fname}: {e}",
                                    None, exc_info=(type(e), e, e.__traceback__))
            log_records.append(rec)
            continue

        try:
            if fname.endswith('.json'):
                config = json.loads(raw)
            elif fname.endswith(('.yaml', '.yml')):
                config = yaml.safe_load(raw)
            elif fname.endswith('.toml'):
                config = toml.loads(raw)
            else:
                rec = logging.LogRecord(__name__, logging.ERROR, fname, 0,
                                        f"Unsupported file extension for {fname}",
                                        None, None)
                log_records.append(rec)
                continue

            if not isinstance(config, dict):
                rec = logging.LogRecord(__name__, logging.ERROR, fname, 0,
                                        f"Configuration in {fname} is not a dictionary",
                                        None, None)
                log_records.append(rec)
                continue

            if resolve_env:
                config = _expand_env(config)

            if overrides and isinstance(overrides, dict):
                # Merge overrides; user values take precedence
                merged = config.copy()
                merged.update(overrides)
                config = merged

            configs[fname] = config

        except Exception as e:
            rec = logging.LogRecord(__name__, logging.ERROR, fname, 0,
                                    f"Failed to parse {fname}: {e}",
                                    None, exc_info=(type(e), e, e.__traceback__))
            log_records.append(rec)

    return configs, log_records<|return|>

