                msg=str(e),
                args=None,
                exc_info=e
            )
            error_records.append(record)
    return parsed_configs, error_records<|return|>

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding
    parsed configuration, and sequence of logging.LogRecord instances containing any parse errors.
    """
    import os, yaml, toml, logging

    parsed_configs = {}
    log_records = []

    def _resolve_env(obj):
        if isinstance(obj, str):
            return os.path.expandvars(obj)
        elif isinstance(obj, dict):
            return {k: _resolve_env(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_resolve_env(v) for v in obj]
        return obj

    for fname in config_filenames:
        if not os.path.exists(fname):
            exc_msg = f"Configuration file not found: {fname}"
            record = logging.LogRecord('config_loader',
                                       logging.ERROR,
                                       fname, 0,
                                       exc_msg, None, None)
            log_records.append(record)
            continue
        try:
            with open(fname, 'r') as f:
                raw = f.read()
        except Exception as exc:
            exc_msg = f"Error reading file {fname}: {exc}"
            record = logging.LogRecord('config_loader',
                                       logging.ERROR,
                                       fname, 0,
                                       exc_msg, None, exc)
            log_records.append(record)
            continue

        config = None
        # Determine format by extension
        ext = os.path.splitext(fname)[1].lower()
        try:
            if ext in {'.yaml', '.yml'}:
                config = yaml.safe_load(raw)
            elif ext == '.toml':
                config = toml.loads(raw)
            else:
                # Try YAML first, then TOML
                try:
                    config = yaml.safe_load(raw)
                except Exception:
                    try:
                        config = toml.loads(raw)
                    except Exception as exc:
                        raise exc
        except Exception as exc:
            exc_msg = f"Error parsing {fname}: {exc}"
            record = logging.LogRecord('config_loader',
                                       logging.ERROR,
                                       fname, 0,
                                       exc_msg, None, exc)
            log_records.append(record)
            continue

        if config is None:
            exc_msg = f"No configuration data loaded from {fname}"
            record = logging.LogRecord('config_loader',
                                       logging.ERROR,
                                       fname, 0,
                                       exc_msg, None, None)
            log_records.append(record)
            continue

        # Apply environment variable resolution if requested
        if resolve_env:
            config = _resolve_env(config)

        # Apply overrides if provided
        if overrides:
            if isinstance(config, dict):
                config.update(overrides)

        parsed_configs[fname] = config

    return parsed_configs, log_records<|return|>

