@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """Return a dictionary of available Bolt protocol handlers, keyed by version tuple.
        If an explicit protocol version is provided, the dictionary will contain either
        zero or one items, depending on whether that version is supported. If no
        protocol version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol version
            (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all relevant
            and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Validate input
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple or None")

        # Helper to collect handlers from subclasses
        handlers = {}

        # First, look for a pre‑defined mapping attribute (common in many frameworks)
        if hasattr(cls, "PROTOCOL_HANDLERS") and isinstance(cls.PROTOCOL_HANDLERS, dict):
            for ver, hcls in cls.PROTOCOL_HANDLERS.items():
                if (
                    isinstance(ver, tuple)
                    and isinstance(hcls, type)
                    and issubclass(hcls, cls)
                ):
                    handlers[ver] = hcls

        # If no mapping attribute or it is incomplete, fall back to introspection
        def _collect(subcls):
            for child in subcls.__subclasses__():
                # Expect subclasses to declare a _protocol_version class attribute
                if hasattr(child, "_protocol_version"):
                    ver = getattr(child, "_protocol_version")
                    if isinstance(ver, tuple):
                        handlers[ver] = child
                _collect(child)

        _collect(cls)

        # If a specific version was requested, narrow the dictionary
        if protocol_version is not None:
            return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}

        return handlers<|return|>

