                return {}

        return handlers<|return|>

@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """
        Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Determine the mapping of version tuples to handler classes.
        # Subclasses may override the mapping via a class attribute
        # named PROTOCOL_HANDLERS. If not defined, fall back to scanning
        # the class namespace for handler classes that expose a
        # _protocol_version attribute.
        handlers = {}
        if hasattr(cls, "PROTOCOL_HANDLERS"):
            handlers = cls.PROTOCOL_HANDLERS
        else:
            for attr_name, obj in vars(cls).items():
                if isinstance(obj, type) and hasattr(obj, "_protocol_version"):
                    handlers[obj._protocol_version] = obj

        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError(
                    "protocol_version must be a tuple, got %s" % type(protocol_version).__name__
                )
            return (
                {protocol_version: handlers[protocol_version]}
                if protocol_version in handlers
                else {}
            )
        return dict(handlers)<|return|>

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    # Determine if seq is a sequence (iterable) but not a string/bytes.
    if isinstance(seq, (bytes, bytearray, str)):
        # Treat as a single element, not a sequence.
        return ([seq], type(seq))
    try:
        iterator = iter(seq)
    except TypeError:
        # seq is not iterable, wrap it in a list.
        return ([seq], type(seq))
    # seq is iterable; check if it is already a list or tuple.
    if isinstance(seq, (list, tuple)):
        return (seq, type(seq))
    # For other iterable types (generators, iterators, etc.), materialise into a list.
    # The bufsize argument is ignored in this implementation.
    return (list(seq), type(seq))<|return|>

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type)."""

    # If seq is already a sequence type (list, tuple, set, etc.) return it directly
    if isinstance(seq, (list, tuple, set)):
        return (seq, type(seq))

    # If seq is a string or bytes, return a list of its elements
    if isinstance(seq, (str, bytes)):
        seq_list = list(seq)
        return (seq_list, type(seq_list))

    # If seq is iterable but not a string/bytes, convert to a list
    if hasattr(seq, "__iter__"):
        if bufsize is None:
            seq_list = list(seq)
        else:
            seq_list = []
            count = 0
            for item in seq:
                seq_list.append(item)
                count += 1
                if count >= bufsize:
                    break
        return (seq_list, type(seq_list))

    # Fallback: return the object itself
    return (seq, type(seq))<|return|>

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a sequence (list or tuple) just return it.
    if isinstance(seq, (list, tuple)):
        return seq, type(seq).__name__
    # Handle string objects separately to avoid treating them as iterables.
    if isinstance(seq, str):
        return seq, 'str'
    if isinstance(seq, bytes):
        try:
            decoded = seq.decode('utf-8', errors='ignore')
        except Exception:
            decoded = seq.decode('latin1', errors='ignore')
        return decoded, 'bytes'
    # File-like objects: read content using optional bufsize.
    if hasattr(seq, 'read'):
        try:
            data = seq.read(bufsize) if bufsize is not None else seq.read()
        except Exception:
            data = ''
        if isinstance(data, bytes):
            try:
                data = data.decode('utf-8', errors='ignore')
            except Exception:
                data = data.decode('latin1', errors='ignore')
        return data, 'file'
    # For generic iterables that are not sequences, create a list.
    try:
        iterator = iter(seq)
    except TypeError:
        # Not iterable, return as is.
        return seq, type(seq).__name__
    # Convert iterable to a list (preserving order if feasible).
    return list(iterator), type(seq).__name__<|return|>

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type)."""
    # Preserve the original type name for reporting
    orig_type = type(seq).__name__
    # Determine the sequence based on the input type
    if isinstance(seq, (list, tuple)):
        sequence = seq
    elif isinstance(seq, (str, bytes)):
        # Turn a string/bytes into a list of its elements
        sequence = list(seq)
    else:
        # Attempt to convert any iterable to a list; otherwise wrap as single element list
        try:
            sequence = list(seq)
        except Exception:
            sequence = [seq]
    # Truncate if requested
    if bufsize is not None:
        sequence = sequence[:bufsize]
    return sequence, orig_type<|return|>

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    errors = []

    # 1. Check that the candidate provides the interface.
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                raise zope.interface.Invalid(
                    "%r does not provide %r" % (candidate, iface)
                )
        except Exception:
            # Using providedBy might raise a TypeError if the candidate
            # cannot be queried; we treat that as a failure.
            errors.append(zope.interface.Invalid(
                "Unable to determine whether %r provides %r" % (candidate, iface)
            ))

    # 2. Check that all declared methods exist and are callable.
    try:
        required_methods = iface.methods()
    except AttributeError:
        required_methods = {}
    for name, iface_sig in required_methods.items():
        if not hasattr(candidate, name):
            errors.append(AttributeError(
                "%r missing required method %r" % (candidate, name)
            ))
            continue
        impl = getattr(candidate, name)
        if not callable(impl):
            errors.append(TypeError(
                "%r attribute %r is not callable" % (candidate, name)
            ))
            continue
        # 3. Check signature match if possible.
        try:
            import inspect
            candidate_sig = inspect.signature(impl)
            # zope.interface stores signatures as strings; convert to inspect.Signature if needed.
            if isinstance(iface_sig, str):
                # This is a rough check: compare the parameter string representations.
                if iface_sig != str(candidate_sig):
                    errors.append(ValueError(
                        "Signature of method %r in %r differs from interface: %s" %
                        (name, candidate, candidate_sig)
                    ))
            else:
                # Assume iface_sig is an inspect.Signature
                if iface_sig != candidate_sig:
                    errors.append(ValueError(
                        "Signature of method %r in %r differs from interface: %s" %
                        (name, candidate, candidate_sig)
                    ))
        except Exception:
            # If we cannot introspect the signature, skip the check.
            pass

    # 4. Check that all declared attributes exist.
    try:
        required_attrs = iface.attributes()
    except AttributeError:
        required_attrs = {}
    for name in required_attrs:
        if not hasattr(candidate, name):
            errors.append(AttributeError(
                "%r missing required attribute %r" % (candidate, name)
            ))

    # 5. Report errors.
    if errors:
        if len(errors) == 1:
            raise errors[0]
        else:
            msg = "%d errors verifying %r against %r" % (
                len(errors), candidate, iface
            )
            raise zope.interface.Invalid(msg)

    return True

<|return|>

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """

    if not isinstance(candidate, type):
        if tentative:
            return False
        raise TypeError("candidate must be a class, got %r" % candidate)

    # If candidate already subclasses iface, that's a quick success.
    if issubclass(candidate, iface):
        return True

    # Collect abstract methods (if any) defined on the interface.
    abstract_methods = getattr(iface, "__abstractmethods__", set())
    for name in abstract_methods:
        if not hasattr(candidate, name):
            if tentative:
                return False
            raise TypeError(
                "candidate %s does not implement required method %s" % (candidate.__name__, name)
            )
        attr = getattr(candidate, name)
        if not callable(attr):
            if tentative:
                return False
            raise TypeError(
                "attribute %s of candidate %s is not callable" % (name, candidate.__name__)
            )

    # If we get here the candidate implements all required methods.
    return True<|return|>

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.

    The function checks that `candidate` defines all the non‑dunder
    attributes that are present on `iface`.  If `tentative` is ``True``
    the function returns ``False`` instead of raising an exception
    when a mismatch is detected; otherwise it raises an informative
    exception.
    """
    # Local helper for raising
    def _raise(name, msg):
        if tentative:
            return False
        raise AttributeError(msg)

    # Determine what constitutes "the interface".
    # *iface* may be a class, a type, or an iterable of attribute names.
    if isinstance(iface, (list, tuple, set)):
        iface_attrs = list(iface)
    else:
        # Get all public attributes (exclude dunder names).
        iface_attrs = [name for name in dir(iface) if not (name.startswith('__') and name.endswith('__'))]

    # Check each attribute.
    for name in iface_attrs:
        if not hasattr(candidate, name):
            return _raise(name, f"candidate {candidate!r} does not provide required attribute '{name}' per interface {iface!r}")

        iface_attr = getattr(iface, name, None)
        cand_attr = getattr(candidate, name)

        # If the interface declares the attribute as a callable,
        # ensure the candidate's attribute is also callable.
        if callable(iface_attr) and not callable(cand_attr):
            return _raise(name, f"attribute '{name}' is callable on interface but not on candidate {candidate!r}")

    return True if not tentative else True
<|return|>

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Resolve the candidate to a class if it is an instance
    if not isinstance(candidate, type):
        candidate = candidate.__class__

    # Gather attributes that are expected to be present on the interface.
    # We ignore special attributes and those not present on the interface.
    iface_attrs = [
        name for name in dir(iface)
        if not name.startswith("_") and hasattr(iface, name)
    ]

    for name in iface_attrs:
        if not hasattr(candidate, name):
            if tentative:
                return False
            raise TypeError(
                f"Candidate {candidate!r} does not implement required attribute "
                f"'{name}' from interface {iface!r}"
            )

        iface_attr = getattr(iface, name)
        cand_attr = getattr(candidate, name)

        # If the interface defines a callable, the candidate must be callable too.
        if callable(iface_attr) and not callable(cand_attr):
            if tentative:
                return False
            raise TypeError(
                f"Attribute '{name}' of candidate {candidate!r} is not callable "
                f"as required by interface {iface!r}"
            )

    return True<|return|>

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # If an explicit metaclass was supplied, we use it only if all base classes
    # (more precisely their metaclasses) are compatible with it.
    if explicit_mc is not None:
        for base in bases:
            try:
                base_meta = type(base)
            except Exception:
                raise TypeError(f"Base {base!r} is not a type")
            if not issubclass(base_meta, explicit_mc):
                raise TypeError(
                    f"metaclass conflict: {explicit_mc!r} is not a supermetaclass "
                    f"of {base_meta!r}"
                )
        return explicit_mc

    # No explicit metaclass: derive it from the bases.
    # If there are no bases, fall back to the built‑in type metaclass.
    try:
        base_iter = iter(bases)
        first = next(base_iter)
        candidate = type(first)
    except StopIteration:
        return type

    for base in base_iter:
        try:
            base_meta = type(base)
        except Exception:
            raise TypeError(f"Base {base!r} is not a type")
        if candidate is base_meta:
            continue
        # Prefer the more derived metaclass
        if issubclass(candidate, base_meta):
            # candidate is more derived, keep it
            continue
        if issubclass(base_meta, candidate):
            candidate = base_meta
            continue
        # Conflict: the two metaclasses are unrelated
        raise TypeError(
            f"metaclass conflict: {candidate!r} is not a supermetaclass of "
            f"{base_meta!r} and vice versa"
        )

    return candidate<|return|>

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass is supplied, use it
    if explicit_mc is not None:
        # Ensure it is a valid class-like object
        try:
            type(explicit_mc)
        except Exception:
            raise TypeError("explicit metaclass must be a type-like object")
        return explicit_mc

    # No bases case defaults to the built-in type
    if not bases:
        return type

    # Start with the metaclass of the first base
    mcls = type(bases[0])

    # Iterate through remaining bases to find a compatible metaclass
    for base in bases[1:]:
        bmcls = type(base)

        # Same metaclass already determined
        if bmcls is mcls:
            continue

        # Prefer the more derived metaclass when possible
        if issubclass(bmcls, mcls):
            mcls = bmcls
            continue
        if issubclass(mcls, bmcls):
            continue

        # Find a common ancestor in the MRO chains
        bmcls_mro = set(bmcls.__mro__)
        for cls in mcls.__mro__:
            if cls in bmcls_mro:
                mcls = cls
                break
        else:
            # No common metaclass could be found
            raise TypeError(
                f"metaclass conflict: {mcls.__name__} and {bmcls.__name__} are incompatible"
            )

    return mcls<|return|>

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    # Extract the metaclasses for each base that is a class type
    metaclasses = [type(b) for b in bases if isinstance(b, type)]

    # No bases (or all are not types); default to the built‑in type
    if not metaclasses:
        return type

    # Start with the metaclass of the first base
    chosen_meta = metaclasses[0]

    # Resolve conflicts by picking the most derived metaclass that is a
    # subclass of all others, otherwise raise a conflict TypeError.
    for m in metaclasses[1:]:
        if issubclass(m, chosen_meta):
            chosen_meta = m
        elif not issubclass(chosen_meta, m):
            raise TypeError(
                f"metaclass conflict: {chosen_meta.__name__!r} vs {m.__name__!r}"
            )
    return chosen_meta<|return|>

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is __marker:
            raise KeyError(key)
        return default
    for map in [self._pb.IntMap, self._pb.FloatMap, self._pb.StringMap,
                self._pb.BoolMap]:
        if key in map.keys():
            return map.pop(key)
    if default is __marker:
        raise KeyError(key)
    return default<|return|>

