    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if default is __marker:
        return super().pop(key)
    return super().pop(key, default)<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('dictionary is empty')
    # Determine the minimum frequency among all keys
    min_freq = min(self._freq.values())
    # Find the first key that has this frequency
    for key, freq in self._freq.items():
        if freq == min_freq:
            break
    value = self._data.pop(key)
    self._freq.pop(key)
    return (key, value)<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('dictionary is empty')
    # Determine the key with the lowest access frequency
    # Assume that `self._freq` stores a mapping of key -> frequency count
    try:
        min_key = min(self._freq, key=lambda k: self._freq.get(k, 0))
    except AttributeError:
        # Fallback if frequency tracking attribute not present: pick the first key
        min_key = next(iter(self))
    # Retrieve and delete the item from the dictionary
    value = self.pop(min_key, None)
    if value is None:
        # In case the key disappeared between lookup and deletion
        raise KeyError(min_key)
    # Optionally remove the frequency record
    if hasattr(self, "_freq"):
        self._freq.pop(min_key, None)
    return (min_key, value)<|return|>

