def verify_relayable_signature(public_key, doc, signature):
    """Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    Returns True if the signature is valid, False otherwise.
    """
    try:
        import base64
        from cryptography.hazmat.primitives import hashes, serialization
        from cryptography.hazmat.primitives.asymmetric import padding
    except Exception:
        # cryptography library not available
        return False

    # Load the public key
    if isinstance(public_key, bytes):
        key_bytes = public_key
    elif isinstance(public_key, str):
        key_bytes = public_key.encode()
        if not key_bytes.startswith(b'-----'):
            # Assume DER if no PEM header
            pass
    else:
        key_bytes = None

    try:
        if key_bytes and key_bytes.startswith(b'-----'):
            key_obj = serialization.load_pem_public_key(key_bytes)
        elif key_bytes:
            key_obj = serialization.load_der_public_key(key_bytes)
        else:
            key_obj = public_key  # Assume already a key object
    except Exception:
        return False

    # Decode the signature from base64
    try:
        sig_bytes = base64.b64decode(signature)
    except Exception:
        return False

    # Compute the signature over the canonicalized XML
    # For simplicity, use the raw UTF-8 bytes of the doc
    msg_bytes = doc.encode('utf-8')

    try:
        key_obj.verify(
            sig_bytes,
            msg_bytes,
            padding.PKCS1v15(),
            hashes.SHA256()
        )
        return True
    except Exception:
        return False<|return|>

