def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    webfinger: Dict[str, any] = {}

    # Try JSON format first
    try:
        data = json.loads(document)
        subject = data.get("subject")
        webfinger["subject"] = subject

        if isinstance(data.get("links"), list):
            for link in data["links"]:
                rel = link.get("rel")
                typ = link.get("type")
                href = link.get("href")
                if rel == "hcard" and typ == "text/html":
                    webfinger["hcard_url"] = href
                if rel == "lrdd":
                    webfinger["lrdd_template"] = href
        return webfinger
    except Exception:
        pass  # Fall back to XRD parsing

    # XRD format
    try:
        root = ET.fromstring(document)
        ns = "{http://docs.oasis-open.org/ns/xri/xrd-1.0}"

        subject_elem = root.find(f"{ns}Subject")
        if subject_elem is not None:
            webfinger["subject"] = subject_elem.text

        for link in root.findall(f"{ns}Link"):
            rel = link.get("rel")
            typ = link.get("type")
            href = link.get("href")
            template = link.get("template")
            url = href or template

            if rel == "hcard" and typ == "text/html":
                webfinger["hcard_url"] = url
            if rel == "lrdd":
                webfinger["lrdd_template"] = url

        return webfinger
    except Exception:
        # If all parsing fails, return empty dict
        return {}
