    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    def _strip_ns(tag: str) -> str:
        return tag.split("}")[-1] if "}" in tag else tag

    # Try JSON first
    try:
        data = json.loads(document)
    except Exception:
        data = None

    if isinstance(data, dict):
        result: Dict = {}
        # Subject
        subject = data.get("subject")
        if subject:
            result["subject"] = subject
        # Links
        for link in data.get("links", []):
            if not isinstance(link, dict):
                continue
            rel = link.get("rel")
            href = link.get("href")
            if rel and href:
                result[rel] = href
        return result

    # Assume XRD (XML)
    try:
        root = ET.fromstring(document)
    except Exception:
        return None

    result: Dict = {}
    # Subject
    subject_elem = root.find(".//*[local-name() = 'Subject']")
    if subject_elem is not None and subject_elem.text:
        result["subject"] = subject_elem.text

    # Links
    for link in root.findall(".//*[local-name() = 'Link']"):
        rel = link.attrib.get("rel")
        href = link.attrib.get("href")
        if rel and href:
