            find = lambda tag: root.find(f"ns:{tag}", ns)
            findall = lambda tag: root.findall(f"ns:{tag}", ns)
        else:
            find = lambda tag: root.find(tag)
            findall = lambda tag: root.findall(tag)

        subject_el = find("Subject")
        if subject_el is not None and subject_el.text:
            result["subject"] = subject_el.text

        for link in findall("Link"):
            rel = link.attrib.get("rel")
            href = link.attrib.get("href")
            if rel and href:
                if rel in ("http://webfinger.net/rel/hcard", "hcard"):
                    key = "hcard_url"
                elif rel == "lrdd":
                    key = "lrdd_url"
                else:
                    key = rel
                result[key] = href

        return result
    except Exception:
        # In case of any parsing error
        return {}
