def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    doc = document.lstrip()
    # Attempt JSON parsing first
    if doc.startswith('{') or doc.startswith('['):
        try:
            return json.loads(doc)
        except Exception:
            logger.exception("JSON webfinger parsing failed")
            return {}
    # Fallback to XRD (XML) parsing
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(doc)
        result: Dict[str, object] = {}
        # Subject
        subject = root.find('{*}Subject')
        if subject is not None and subject.text:
            result['subject'] = subject.text
        # Aliases
        aliases = [a.text for a in root.findall('{*}Alias') if a.text]
        if aliases:
            result['aliases'] = aliases
        # Links
        links = []
        for link in root.findall('{*}Link'):
            rel = link.get('rel')
            href = link.get('href')
            link_dict: Dict[str, str] = {}
            if rel:
                link_dict['rel'] = rel
            if href:
                link_dict['href'] = href
            type_attr = link.get('type')
            if type_attr:
                link_dict['type'] = type_attr
            if link_dict:
                links.append(link_dict)
        if links:
            result['links'] = links
        return result
    except Exception:
        logger.exception("XRD webfinger parsing failed")
        return {}<|return|>

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
