def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    # Extract host from handle; handle is expected in form user@host
    try:
        host = handle.split("@")[1]
    except Exception:
        # Handle the case where the handle is not in the expected format
        return None
    # Construct the WebFinger URL as per RFC7033
    resource = f"acct:{handle}"
    try:
        encoded_resource = urllib.parse.quote(resource)
    except Exception:
        return None
    url = f"https://{host}/.well-known/webfinger?resource={encoded_resource}"
    # Perform the request and return the body on success
    try:
        with urllib.request.urlopen(url) as response:
            # Read and decode the response content
            return response.read().decode("utf-8")
    except Exception:
        # If anything goes wrong, silently return None
        return None<|return|>

