def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    def _collect(directory):
        try:
            return [
                os.path.join(directory, fname)
                for fname in os.listdir(directory)
                if os.path.isfile(os.path.join(directory, fname))
                and fname.endswith(spec_option)
            ]
        except OSError:
            return []

    file_list = []
    if isinstance(settings_dirs, (list, tuple)):
        for dir_path in settings_dirs:
            file_list.extend(_collect(dir_path))
    else:
        file_list = _collect(settings_dirs)

    return sorted(set(file_list))<|return|>

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
