    try:
        files = []
        for d in settings_dirs:
            for entry in os.listdir(d):
                if entry.endswith(spec_option):
                    files.append(os.path.join(d, entry))
        return sorted(files)
    except (OSError, AttributeError):
        return []<|return|>

