@classmethod
def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("spec_content argument is required")

    # Parse YAML content
    try:
        data = yaml.safe_load(spec_content)
    except Exception as e:
        raise IRValidatorException(f"Could not parse YAML: {e}")

    if data is None or not isinstance(data, dict):
        raise IRValidatorException("Spec must be a mapping")

    # Load the default schema
    try:
        default_schema = json.load(open(cls.default_schema_file, 'r'))
    except Exception as e:
        raise IRValidatorException(f"Could not load default schema: {e}")

    # Validate against the appropriate schema
    try:
        if 'type' in data:
            custom_schema = cls.load_custom_schema(data['type'])
            json_validate(data, custom_schema)
        else:
            json_validate(data, default_schema)
    except ValidationError as ve:
        raise IRValidatorException(f"Validation error: {ve.message} in {ve.instance}")

    return data<|return|>

