def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    # Recursive walk - merge any 'include' dictionaries into their parent
    if not isinstance(parser_dict, dict):
        return parser_dict
    # Extract any include directive first
    include_block = parser_dict.pop('include', None)
    # Process nested dictionaries first
    for key, value in list(parser_dict.items()):
        if isinstance(value, dict):
            parser_dict[key] = self._include_groups(value)
    # Merge the include block after nested processing so that included keys
    # can overwrite existing ones if needed
    if isinstance(include_block, dict):
        for inc_key, inc_val in include_block.items():
            parser_dict[inc_key] = self._include_groups(inc_val)
    return parser_dict<|return|>

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    includes = parser_dict.pop('include', [])
    if not isinstance(includes, (list, tuple)):
        includes = [includes]
    for name in includes:
        group = parser_dict.pop(name, None)
        if group is None:
            continue
        if isinstance(group, dict):
            # Recursively resolve nested includes
            self._include_groups(group)
            parser_dict.update(group)
    return parser_dict<|return|>

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    # The include directive can specify either a list of group names
    # or a dict mapping group names to override values.
    # If no include directive is present, just return the dictionary.
    includes = parser_dict.pop('include', None)
    if not includes:
        return parser_dict

    # Helper to get a spec by name.  Default to an empty dict if not found.
    def _get_spec(name):
        spec = getattr(self, 'parsers', {}).get(name)
        if spec is None:
            raise KeyError(f'Unknown include specification: {name!r}')
        return spec

    # Resolve includes that are a list of group names.
    if isinstance(includes, (list, tuple)):
        for name in includes:
            spec = _get_spec(name)
            parser_dict.update(self._include_groups(spec.copy()))
    # Resolve includes that are a dict mapping group names to overrides.
    elif isinstance(includes, dict):
        for name, overrides in includes.items():
            spec = _get_spec(name)
            spec = self._include_groups(spec.copy())
            if isinstance(overrides, dict):
                spec.update(overrides)
            parser_dict.update(spec)
    else:
        # If a single string is provided, treat it as a single group name.
        if isinstance(includes, str):
            spec = _get_spec(includes)
            parser_dict.update(self._include_groups(spec.copy()))
        else:
            raise TypeError(
                f'Invalid type for include directive: {type(includes).__name__}'
            )

    return parser_dict<|return|>

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    def _merge_into(target):
        include = target.pop('include', None)
        if include is None:
            return
        if isinstance(include, str):
            # comma‑separated list
            include = [i.strip() for i in include.split(',') if i.strip()]
        for inc in include:
            # try the class‑specific loader if available
            loader = getattr(self, "_load_spec", None)
            if loader is None:
                raise RuntimeError(
                    f"_include_groups needs a '_load_spec' method to load {inc!r}"
                )
            inc_dict = loader(inc)
            if not isinstance(inc_dict, dict):
                raise TypeError(
                    f"_load_spec({inc!r}) returned non‑dict: {type(inc_dict).__name__}"
