    for arg in getattr(self, "args", []):
        if not isinstance(arg, _BaseOpt):
            continue
        name = arg.name
        # Use the argument's default if the spec didn't provide one
        if name not in defaults and not isinstance(arg.default, NoDefault):
            defaults[name] = arg.default
        # For dictionary options, merge nested defaults recursively
        if isinstance(arg, DictOption) and arg.scheme:
            sub_defaults = arg.scheme.get_spec_defaults()
            if name in defaults and isinstance(defaults[name], dict):
                defaults[name] = {**defaults[name], **sub_defaults}
