def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    for arg in self.args:
        # Skip any non-option arguments
        if not isinstance(arg, _BaseOpt):
            continue

        # Prefer values provided in the spec; fall back to the option's default.
        # If the spec has the attribute set to None, we treat it as unspecified.
        val = getattr(self.spec, arg.name, None)
        if val is None:
            # If no default is defined for this option, skip it.
            if isinstance(arg.default, NoDefault):
                continue
            val = arg.default

        # For dictionary options, recursively merge spec values with nested defaults.
        if isinstance(arg, DictOption) and arg.scheme:
            if isinstance(val, dict):
                sub_defaults = dict(val)
                sub_defaults.update(arg.scheme.build_defaults())
                val = sub_defaults
            else:
                val = arg.scheme.build_defaults()

        defaults[arg.name] = val
    return defaults<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    spec_source = {}
    if hasattr(self, 'spec'):
        # spec may be a dict-like or an object with a 'spec' attribute
        if isinstance(self.spec, dict):
            spec_source = self.spec
        elif hasattr(self.spec, 'spec'):
            spec_source = self.spec.spec
    for arg in self.args:
        # Skip non-option types, but raise an error if encountered
        try:
            is_opt = isinstance(arg, _BaseOpt)
        except NameError:
            # If _BaseOpt is not defined, assume everything is valid
            is_opt = True
        if not is_opt:
            try:
                raise errors.InvalidSchemeError('Unable to resolve non-Option type')
            except NameError:
                continue
        # Resolve value from spec if present, otherwise fallback to default
        if arg.name in spec_source:
            defaults[arg.name] = spec_source[arg.name]
        elif not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default
        # Handle nested DictOption schemas recursively
        try:
            is_dict_opt = isinstance(arg, DictOption)
        except NameError:
            is_dict_opt = False
        if is_dict_opt and isinstance(arg, DictOption):
            if arg.scheme:
                sub_spec = spec_source.get(arg.name, {})
                if isinstance(sub_spec, dict):
                    defaults[arg.name] = sub_spec
                else:
                    defaults[arg.name] = arg.scheme.get_spec_defaults()
    return defaults<|return|>

def get_spec_defaults(self):
