    defaults = {}
    # Assume the spec may expose its arguments via an 'args' or 'options' attribute
    spec_items = getattr(self.spec, 'args', None) or getattr(self.spec, 'options', [])
    for arg in spec_items:
        if not hasattr(arg, 'name'):
            # Skip items that are not option-like objects
            continue

        # Use the default value if the option defines one
        if hasattr(arg, 'default') and arg.default is not None:
            defaults[arg.name] = arg.default

        # If the option is a dict-like option with its own scheme,
        # recursively pull defaults from that nested scheme
        if hasattr(arg, 'scheme') and isinstance(arg, DictOption):
            nested = None
            if hasattr(arg.scheme, 'build_defaults'):
                nested = arg.scheme.build_defaults()
            if isinstance(nested, dict) and nested:
                defaults[arg.name] = nested

    return defaults<|return|>

