    :param answer_file_args:  the dict of arguments from files
    """
    # mapping of deprecated argument name -> new argument name
    deprecated_map = getattr(self, "deprecated_arg_map", {})
    for deprecated, new in deprecated_map.items():
        for src, src_name in [(cli_args, "command line"), (answer_file_args, "answer file")]:
            if deprecated in src:
                value = src[deprecated]
                print(
                    f"Deprecated argument '{deprecated}' from {src_name} will be deprecated; "
                    f"use '{new}' instead. Value: {value}"
                )<|return|>

