    # none are found.
    specs = getattr(self, "_parser_options", {})
    if not isinstance(specs, dict):
        specs = {}
    # Some implementations use a different attribute name
    if not specs and hasattr(self, "_command_options"):
        specs = getattr(self, "_command_options", {})
    if not specs or not isinstance(specs, dict):
        raise ValueError("No parser option specifications found on this object.")

    if command_name not in specs:
        raise KeyError(
            f"Command '{command_name}' not found in parser options. "
            f"Available commands: {list(specs.keys())!r}"
