    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    if not args:
        return []
    silent = []
    for arg in args:
        if arg.startswith("--silent") or arg.startswith("-s"):
            name = arg.lstrip('-')
            if '=' in name:
                name = name.split('=', 1)[0]
            silent.append(name)
