def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # Normalize the input to a mapping of argument names to values.
    if hasattr(args, '__dict__'):
        items = vars(args).items()
    elif isinstance(args, dict):
        items = args.items()
    else:
        items = [(k, getattr(args, k)) for k in dir(args)
                 if not k.startswith('_') and not callable(getattr(args, k))]

    silent = []
    for name, value in items:
        # Treat boolean False, numeric 0, empty sequences or None as silenced.
        if isinstance(value, bool) and not value:
            silent.append(name)
        elif isinstance(value, (int, float)) and value == 0:
            silent.append(name)
        elif isinstance(value, (list, tuple, set, dict)) and not value:
            silent.append(name)
        elif value is None or (isinstance(value, str) and value == ''):
            silent.append(name)
    return silent<|return|>

