def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    # Normalize args to a dict if it is a list or tuple, otherwise use as is
    arg_dict = args if isinstance(args, dict) else {}
    for opt in options_spec:
        req_when = opt.get('required_when')
        if not req_when:
            continue
        matched = False
        # Function: call with potentially args and command_name
        if callable(req_when):
            try:
                matched = bool(req_when(arg_dict, command_name))
            except TypeError:
                matched = bool(req_when(arg_dict))
        # Dict: treat as key/value conditions or special 'command' key
        elif isinstance(req_when, dict):
            # All conditions must hold
            cond_ok = True
            for key, expected in req_when.items():
                if key == 'command':
                    cond_ok = cond_ok and (command_name == expected)
                else:
                    cond_ok = cond_ok and (arg_dict.get(key) == expected)
            matched = cond_ok
        # List or tuple: any condition in the sequence that evaluates to true
        elif isinstance(req_when, (list, tuple)):
            for cond in req_when:
                if callable(cond):
                    try:
                        if cond(arg_dict, command_name):
                            matched = True
                            break
                    except TypeError:
                        if cond(arg_dict):
                            matched = True
                            break
                elif isinstance(cond, dict):
                    cond_ok = True
                    for key, expected in cond.items():
                        if key == 'command':
                            cond_ok = cond_ok and (command_name == expected)
                        else:
                            cond_ok = cond_ok and (arg_dict.get(key) == expected)
                    if cond_ok:
                        matched = True
                        break
                else:
                    # Treat as presence of key with truthy value
                    if arg_dict.get(cond):
                        matched = True
                        break
        # String: presence of a keyword with truthy value or equals number
        elif isinstance(req_when, str):
            if req_when in arg_dict and arg_dict[req_when]:
                matched = True
            elif req_when == command_name:
                matched = True
        if matched:
            # The option's name may be under different keys; try 'name', else 'long', else 'short'
            name = opt.get('name')
            if not name:
                name = opt.get('long')
            if not name:
                name = opt.get('short')
            if name:
                required.append(name)
    return required<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    def _get_value(source, key):
        if isinstance(source, dict):
            return source.get(key)
        return getattr(source, key, None)

    matched = []
    for opt in options_spec:
        required_when = opt.get('required_when')
        if not required_when:
            continue
        conditions = required_when if isinstance(required_when, (list, tuple)) else [required_when]
        for cond in conditions:
            if isinstance(cond, dict):
                ok = True
                for key, expected in cond.items():
                    val = _get_value(args, key)
                    if isinstance(expected, (list, tuple)):
                        if val not in expected:
                            ok = False
                            break
                    else:
                        if val != expected:
                            ok = False
                            break
                if ok:
                    name = opt.get('name', opt.get('arg'))
                    if name:
                        matched.append(name)
                    break
    return matched<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for spec in options_spec:
        # skip if spec does not declare a name
        name = spec.get("name")
        if not name:
            continue

        cond = spec.get("required_when")
        if not cond:
            continue

        try:
            if callable(cond):
                # callable is expected to accept: command_name, args_dict
                satisfied = bool(cond(command_name, args))
            elif isinstance(cond, (list, tuple, set)):
                # required when all options in the iterable are truthy
                satisfied = all(args.get(opt_name) for opt_name in cond)
            elif isinstance(cond, dict):
                # required when each key matches the expected value
                satisfied = all(args.get(k) == v for k, v in cond.items())
            else:
                # treat as a simple option name, required when it is truthy
                satisfied = bool(args.get(cond))
        except Exception:
            # any error evaluating the condition means it is not satisfied
            satisfied = False

        if satisfied:
            required.append(name)

    return required<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        if 'required_when' not in opt:
            continue
        condition = opt['required_when']
        # Skip if condition is None or False
        if not condition:
            continue
        matched = False
        # Condition may be a mapping of required arg values
        if isinstance(condition, dict):
            matched = all(
                args.get(k) == v
                for k, v in condition.items()
            )
        # Condition may be an iterable of arg names that must be present
        elif isinstance(condition, (list, tuple, set)):
            matched = all(
                k in args and args[k]
                for k in condition
            )
        # Condition may be a simple arg name that must be truthy
        else:
            matched = bool(args.get(condition))
        if matched:
            required.append(opt.get('dest') or opt.get('name'))
    return required<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    # Resolve options_spec iterable form
    if isinstance(options_spec, dict):
        spec_iter = list(options_spec.items())
    else:
        # assume list/tuple of spec dicts
        spec_iter = []
        for spec in options_spec:
            # option spec can have key as name
            if isinstance(spec, dict):
                # try to infer name
                opt_name = spec.get('arg') or spec.get('name')
                if opt_name is not None:
                    spec_iter.append((opt_name, spec))
                else:
                    # fallback: use the spec itself if it's a tuple
                    if isinstance(spec, (list, tuple)) and len(spec) == 2:
                        spec_iter.append((spec[0], spec[1]))
            else:
                # non-dict entries are ignored
                continue

    for opt_name, spec in spec_iter:
        cond = spec.get('required_when')
        if not cond:
            continue

        matched = False
        try:
            if callable(cond):
                matched = bool(cond(command_name, args))
            elif isinstance(cond, dict):
                # e.g., {"flag": True} or {"flag": "value"}
                matched = True
                for key, value in cond.items():
                    if value is None:
                        # just check existence and truthiness
                        if not bool(args.get(key)):
                            matched = False
                            break
                    else:
                        if args.get(key) != value:
                            matched = False
                            break
            else:
                # any non-callable, non-dict truthy value is considered
                matched = bool(cond)
        except Exception:  # pragma: no cover
            matched = False

        if matched:
            required.append(opt_name)
    return required<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Load argument specifications from parsed YAML.
    arg_specs = self.parsed_yaml.get('args', {})

    # Prepare list of (arg_name, value) pairs.
    if isinstance(args, dict):
        arg_items = list(args.items())
    else:
        arg_items = []
        for arg in args:
            # Ensure each list item is a dictionary with a single key-value pair.
            self._assert_command_dict(arg, '[list-item]', [])
            if len(arg) != 1:
                abort(f"List item for arguments must contain exactly one key-value pair, got {len(arg)}")
            key, val = next(iter(arg.items()))
            arg_items.append((key, val))

    # Iterate over each argument and validate its length against the spec.
    for arg_name, value in arg_items:
        spec = arg_specs.get(arg_name, {})
        max_len = spec.get('length')
        if max_len is None:
            continue  # No length restriction for this argument.

        # Determine the length of the value in a robust way.
        try:
            val_len = len(value)
        except Exception:
            val_len = len(str(value))

        if val_len > max_len:
            abort(
                f"Argument '{arg_name}' has length {val_len}, "
                f"which exceeds the maximum allowed length of {max_len}"
            )
<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments as a mapping of argument name to value.
    """
    # argspec for length constraints is expected to be available in self.parsed_yaml['args']
    arg_specs = self.parsed_yaml.get('args', {})
    for name, value in args.items():
        spec = arg_specs.get(name, {})
        max_len = spec.get('max_length')
        if max_len is None:
            continue
        if value is None:
            continue
        try:
            val_len = len(value)
        except TypeError:
            continue  # value has no length, skip
        if val_len > max_len:
