def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Retrieve the args specification from the parsed YAML configuration
    args_spec = self.parsed_yaml.get('args', {})
    for arg_name, arg_value in args.items():
        # Grab the argument specification for the current argument
        spec = args_spec.get(arg_name, {})
        # Find the maximum allowed length (support a few common key names)
        max_len = None
        for key in ('max_length', 'maxlength', 'len'):
            if key in spec:
                max_len = spec[key]
                break
        if max_len is None:
            # No length restriction for this argument
            continue
        # Skip length checks for non-iterable values
        if not hasattr(arg_value, '__len__'):
            continue
        try:
            current_len = len(arg_value)
        except TypeError:
            # If len() fails, treat as no length restriction
            continue
        if current_len > max_len:
            raise ValueError(
                f"Argument '{arg_name}' length {current_len} exceeds "
                f"maximum allowed length {max_len}"
            )<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # args can be a dict mapping arg names to attribute dicts
    # or a list of such dicts (each with one key-value pair).
    if isinstance(args, dict):
        arg_items = args.items()
    else:  # assume list-like
        arg_items = []
        for argdict in args:
            if isinstance(argdict, dict):
                # each dict should have exactly one key
                if len(argdict) == 1:
                    arg_items.append(list(argdict.items())[0])
    for name, attrs in arg_items:
        # attrs should be a dict containing 'value' and optional 'max_length'
        if not isinstance(attrs, dict):
            continue
        value = attrs.get('value')
        if value is None:
            continue
        # Only objects that have a length can be checked
        if not hasattr(value, '__len__'):
            continue
        max_len = attrs.get('max_length')
        if max_len is None:
            continue
        try:
            if len(value) > max_len:
                raise ValueError(
                    f"Argument '{name}' length {len(value)} exceeds maximum {max_len}"
                )
        except TypeError:
            # value does not support len(), ignore
            continue<|return|>

def validate_length_args(self, args):
