    arg_defs = self.parsed_yaml.get('args', {})

    for arg_name, arg_attrs in arg_defs.items():
        # Each argument may specify a maximum allowed length via the 'length' key
        max_len = None
        if isinstance(arg_attrs, dict):
            max_len = arg_attrs.get('length')
        else:
            # In case arg_attrs is a list of dictionaries, pick the first dict
            if isinstance(arg_attrs, list) and arg_attrs:
                max_len = arg_attrs[0].get('length')

        if max_len is None:
            continue  # No length constraint defined for this argument

        if arg_name not in args:
            continue  # Argument not supplied; nothing to validate

        value = args[arg_name]
        try:
            current_len = len(value)
        except TypeError:
            # Value does not support len(), skip length check for this arg
            continue

        if current_len > max_len:
            raise ValueError(
                f"Argument '{arg_name}' length {current_len} exceeds "
                f"maximum allowed length {max_len}."
