def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Mapping of argument names to the list of allowed choices.  This
    # attribute may be defined by subclasses; if it does not exist
    # or is not a dict, there is nothing to validate.
    choices_map = getattr(self, 'choices', None)
    if not isinstance(choices_map, dict):
        return

    for name, value in args.items():
        if name not in choices_map:
            continue

        allowed = choices_map[name]
        if value not in allowed:
            raise ValueError(
                f"Invalid value for argument `{name}`: {value!r}. "
                f"Allowed choices are {allowed!r}."
            )<|return|>

def validate_choices_args(self, args):
