        arg_spec = getattr(self, 'args', {}).get(arg_name, {})
        if not isinstance(arg_spec, dict):
            continue
        # If there are defined choices, validate the value
        if "choices" in arg_spec:
            if value not in arg_spec["choices"]:
                allowed = ", ".join(map(str, arg_spec["choices"]))
                raise ValueError(
                    f"Invalid choice for '{arg_name}': {value!r}. "
                    f"Allowed values: {allowed}"
