def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Convert argparse.Namespace or other mappings to a dict
    if not isinstance(args, dict):
        try:
            args = vars(args)
        except Exception:
            raise TypeError("args must be a dict or namespace-like object")

    # Helper to validate a single mapping of argument values
    def _validate(mapping):
        # self.arg_choices should map argument names to an iterable of allowed values
        arg_choices = getattr(self, "arg_choices", {})
        for name, value in mapping.items():
            if name not in arg_choices:
                continue  # not a choice argument
            choices = arg_choices[name]
            if isinstance(value, (list, tuple)):
                for v in value:
                    if v not in choices:
                        raise ValueError(
                            f"Invalid value for argument `{name}`: {v!r}. "
                            f"Expected one of: {sorted(choices)}"
                        )
            else:
                if value not in choices:
                    raise ValueError(
                        f"Invalid value for argument `{name}`: {value!r}. "
                        f"Expected one of: {sorted(choices)}"
                    )

    # Support list of argument dicts (e.g., multiple positional args)
    if isinstance(args, list):
        for item in args:
            if isinstance(item, dict):
                _validate(item)
            else:
                raise TypeError("list items must be dicts when validating choice args")
    else:
        _validate(args)<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # support both mapping and sequence of values
    if isinstance(args, dict):
        iterator = args.items()
    else:
        iterator = enumerate(args)

    for name, arg in iterator:
        # determine the value to validate and its bounds
        if isinstance(arg, dict):
            # expect dict with keys: "value", "min", "max"
            value = arg.get("value")
            min_val = arg.get("min")
            max_val = arg.get("max")
        else:
            value = arg
            # try to fetch min/max from attributes of the object
            min_val = getattr(arg, "min", None)
            max_val = getattr(arg, "max", None)

        # skip if bounds are not defined
        if min_val is None or max_val is None:
            continue

        # validate the value
        if value < min_val or value > max_val:
            raise ValueError(
                f"{name!s}: value {value!r} out of range [{min_val!r}, {max_val!r}]"
            )
    return args<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args is iterable
    if not isinstance(args, (list, tuple, set)):
        raise TypeError("args must be an iterable of values")

    # Retrieve min and max from the instance (if defined)
    min_val = getattr(self, "min_", None)
    max_val = getattr(self, "max_", None)

    if min_val is None and max_val is None:
        raise AttributeError("Instance must define at least one of min_ or max_ attributes")

    for value in args:
        if min_val is not None and value < min_val:
            raise ValueError(f"value {value} is below minimum {min_val}")
        if max_val is not None and value > max_val:
            raise ValueError(f"value {value} is above maximum {max_val}")

    return args<|return|>

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: Iterable of tuples. Each tuple can be either
        (value, min_, max_) or (value, (min_, max_)).
    """
    for item in args:
        if not isinstance(item, tuple):
            raise TypeError("Each argument must be a tuple")
        if len(item) == 3:
            value, min_, max_ = item
        elif len(item) == 2:
            value, limits = item
            if isinstance(limits, (list, tuple)) and len(limits) == 2:
                min_, max_ = limits
            else:
                raise ValueError("Invalid limits for argument")
        else:
            raise ValueError("Argument tuple must be of length 2 or 3")
        if min_ is not None and value < min_:
            raise ValueError(f"{value} is less than minimum {min_}")
        if max_ is not None and value > max_:
            raise ValueError(f"{value} is greater than maximum {max_}")
    return args<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for arg in args:
        if not isinstance(arg, (tuple, list)) or len(arg) < 3:
            raise TypeError(
                "Each argument must be a sequence of at least three elements: value, min, max")
        value, min_val, max_val = arg[0], arg[1], arg[2]
        if min_val is not None and value < min_val:
            raise ValueError(f"value {value} is below minimum {min_val}")
        if max_val is not None and value > max_val:
            raise ValueError(f"value {value} is above maximum {max_val}")
    return args<|return|>

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict
    for e in extra_vars:
        if isinstance(e, dict):
            vars_dict.update(e)
        elif isinstance(e, (list, tuple)):
            for item in e:
                if isinstance(item, (list, tuple)) and len(item) == 2:
                    key, value = item
                    vars_dict[key] = value
        # ignore unsupported types
    return vars_dict<|return|>

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    def _to_dict(data):
        if isinstance(data, dict):
            return data
        if data is None:
            return {}
        if isinstance(data, list):
            out = {}
            for item in data:
                if isinstance(item, dict):
                    out.update(item)
            return out
        return {str(data): data}

    if vars_dict is None:
        vars_dict = {}
    vars_dict = _to_dict(vars_dict)

    if not extra_vars:
        return vars_dict

    extra_dict = _to_dict(extra_vars)
    merged = dict(vars_dict)
    merged.update(extra_dict)
    return merged<|return|>

