def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    command = ["ansible-playbook"]
    if verbose:
        try:
            lvl = int(verbose)
            if lvl > 0:
                command.append("-" + "v" * lvl)
        except Exception:
            pass
    for k, v in (ansible_args or {}).items():
        arg = f"--{k}"
        if isinstance(v, bool):
            if v:
                command.append(arg)
            continue
        if isinstance(v, (list, tuple)):
            command.extend([arg, ",".join(map(str, v))])
        else:
            command.append(f"{arg}={v}")
    if extra_vars:
        command.append("--extra-vars")
        command.append(json.dumps(extra_vars))
    command.append(playbook_path)
    try:
        result = subprocess.run(
            command,
            capture_output=True,
            text=True,
            check=True
        )
        return result.stdout
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"Ansible returned error {exc.returncode}: {exc.stderr}") from exc<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Retrieve the type information for this parser if available.
    # It is expected that subclasses provide a mapping `self.arg_types`
    # in the form {parser_name: {arg_name: type_constructor}}
    types_by_parser = getattr(self, 'arg_types', {})
    arg_types = types_by_parser.get(parser_name, {})

    for arg_name, converter in arg_types.items():
        if arg_name in values_dict:
            raw_value = values_dict[arg_name]
            try:
                # If the type constructor is callable (e.g., int, float, bool, list),
                # use it directly. For bool we need special handling of common string values.
                if converter is bool:
                    if isinstance(raw_value, str):
                        values_dict[arg_name] = raw_value.lower() in ('true', '1', 'yes', 'on')
                    else:
                        values_dict[arg_name] = bool(raw_value)
                else:
                    values_dict[arg_name] = converter(raw_value)
            except Exception:
                # If conversion fails, leave the original string value untouched.
                pass

    # If no explicit type mapping is provided, try simple in‑place conversions:
    for key, val in values_dict.items():
        if isinstance(val, str):
            # Boolean
            lower = val.lower()
            if lower in ('true', '1', 'yes', 'on'):
                values_dict[key] = True
                continue
            if lower in ('false', '0', 'no', 'off'):
                values_dict[key] = False
                continue
            # Integer
            try:
                values_dict[key] = int(val)
                continue
            except (ValueError, TypeError):
                pass
            # Float
            try:
                values_dict[key] = float(val)
                continue
            except (ValueError, TypeError):
                pass
            # Comma‑separated list
            if ',' in val:
                values_dict[key] = [v.strip() for v in val.split(',')]

    # The method mutates `values_dict` in place; it returns None.<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Retrieve the parser definition for the given command
    parser = getattr(self, "parsers", {}).get(parser_name)
    if parser is None:
        # No parser available, nothing to convert
        return values_dict

    # Get the option mapping; this may be stored under different names
    options = getattr(parser, "options", {})
    # Fallback to other common attribute names if not found
    if not options:
        options = getattr(parser, "options_by_name", {})
    if not options:
        options = getattr(parser, "_options", {})
    if not options:
        options = getattr(parser, "get_option", lambda k: None)  # function

    # If options is a function, wrap in a simple callable retrieval
    def _get_option(name):
        if callable(options):
            try:
                opt = options(name)
                return opt if opt is not None else None
            except Exception:
                return None
        else:
            return options.get(name)

    # Iterate through provided values and try to apply the conversion
    for key, raw_val in list(values_dict.items()):
        opt = _get_option(key)
        if opt and hasattr(opt, "convert"):
            try:
                values_dict[key] = opt.convert(raw_val)
            except Exception:
                # If conversion fails, keep the raw string value
                pass
        else:
            # When no explicit conversion is available,
            # perform basic type inference for common literals.
            if isinstance(raw_val, str):
                if raw_val.lower() in {"true", "yes", "1"}:
                    values_dict[key] = True
                elif raw_val.lower() in {"false", "no", "0"}:
                    values_dict[key] = False
                else:
                    # Try int and float conversions
                    try:
                        if "." in raw_val:
                            values_dict[key] = float(raw_val)
                        else:
                            values_dict[key] = int(raw_val)
                    except Exception:
                        # Leave as string if all conversions fail
                        pass

    return values_dict<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Retrieve the option objects for the specified parser.
    # The options container may be named `parsers`, `options`, or
    # something similar.  Look up safely.
    options = getattr(self, 'parsers', {}).get(parser_name, [])
    if not options:
        options = getattr(self, 'options', {}).get(parser_name, [])
    if not options:
        # No options registered for this parser; nothing to convert.
        return values_dict

    for opt in options:
        # Skip options that were not provided.
        if opt.name not in values_dict:
            continue

        raw_value = values_dict[opt.name]

        # Preserve empty strings as-is (they often represent
        # "no value supplied" in CLI parsing).
        if raw_value == "":
            continue

        # Preferred: use the option's own conversion routine.
        convert = getattr(opt, 'convert', None)
        if callable(convert):
            try:
                values_dict[opt.name] = convert(raw_value)
                continue
            except Exception:
                pass

        # Fallback: use a declared type attribute if present.
        opt_type = getattr(opt, 'type', None)
        if callable(opt_type):
            try:
                values_dict[opt.name] = opt_type(raw_value)
                continue
            except Exception:
                pass

        # Last resort: perform a very generic type inference.
        try:
            if isinstance(raw_value, str):
                lowered = raw_value.lower()
                if lowered in ("true", "false"):
                    values_dict[opt.name] = lowered == "true"
                elif '.' in raw_value:
                    values_dict[opt.name] = float(raw_value)
                else:
                    values_dict[opt.name] = int(raw_value)
        except Exception:
            # If inference fails, leave the original string value.
            pass

    return values_dict<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os, json
    # Locate the plugin spec file
    for spec_name in ("plugin.json", "manifest.json", "package.json"):
        spec_path = os.path.join(plugin_dir, spec_name)
        if os.path.isfile(spec_path):
            break
    else:
        return {}
    # Load the spec JSON
    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            spec_data = json.load(f)
    except Exception:
        return {}
    # Recursively flatten dictionary keys
    flat_dict = {}

    def _flatten(item, parent_key=""):
        if isinstance(item, dict):
            for k, v in item.items():
                new_key = f"{parent_key}.{k}" if parent_key else k
                _flatten(v, new_key)
        else:
            flat_dict[parent_key] = item

    _flatten(spec_data)
    return flat_dict
<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
