    for fname in ("plugin.yml", "plugin.yaml", "plugin.json"):
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            spec_file = path
            break

    if spec_file is None:
        return {}

    # Load the spec
    with open(spec_file, "r", encoding="utf-8") as f:
        if spec_file.endswith(".json"):
            spec = json.load(f)
        else:
            if yaml is None:
                raise ImportError("PyYAML is required to parse YAML plugin specifications.")
            spec = yaml.safe_load(f)

    # Flatten nested dictionaries
    flat = {}

    def _flatten(current_prefix, obj):
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_prefix = f"{current_prefix}.{k}" if current_prefix else k
                _flatten(new_prefix, v)
        else:
            flat[current_prefix] = obj

    _flatten("", spec)
    return flat
