        with open(spec_path, "r", encoding="utf-8") as f:
            spec = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}

    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return _flatten(spec)<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os, json
    try:
        import yaml
    except ImportError:
        yaml = None

    # Find the spec file
    spec_path = None
    for name in ("plugin.json", "plugin.yaml", "plugin.yml"):
        path = os.path.join(plugin_dir, name)
        if os.path.isfile(path):
            spec_path = path
            break
    if spec_path is None:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    # Load the spec
    with open(spec_path, "r", encoding="utf-8") as f:
        if spec_path.endswith(".json"):
            spec = json.load(f)
        else:
            if yaml is None:
                raise RuntimeError("yaml package is required to load YAML spec files")
            spec = yaml.safe_load(f)

    # Flatten the dict
    def _flatten(d, parent_key=""):
        flat = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                flat.update(_flatten(v, new_key))
            else:
                flat[new_key] = v
        return flat

    return _flatten(spec)<|return|>

